import { Injectable } from '@nestjs/common';
import {
  DeckPoolService,
  DeckPoolState,
} from '../../../../modules/cards/services/deck-pool.service';
import {
  PanierExpressDeckPool,
  PanierExpressMetadata,
} from '../model/panier-express-state.entity';
import { RandomService } from '../../../../modules/random/services/random.service';

@Injectable()
export class PanierExpressDeckService {
  constructor(
    private readonly deckPool: DeckPoolService,
    private readonly random: RandomService,
  ) {}

  drawCard<T = string>(
    meta: PanierExpressMetadata,
    key: string,
  ): {
    card: T | null;
    metadata: PanierExpressMetadata;
  } {
    const metaRng = this.random.createMetaRng(meta as any);
    const { card, pool } = this.deckPool.draw<T>(
      meta.decks as DeckPoolState<T>,
      key,
      metaRng.rng,
    );
    return {
      card: card ?? null,
      metadata: {
        ...metaRng.getMeta(),
        decks: pool as PanierExpressDeckPool,
      },
    };
  }

  drawWithReplenish<T = string>(
    meta: PanierExpressMetadata,
    key: string,
    replenish: () => T[],
  ): {
    card: T | null;
    metadata: PanierExpressMetadata;
  } {
    const initial = this.drawCard<T>(meta, key);
    if (initial.card) {
      return initial;
    }
    const cards = replenish();
    if (!Array.isArray(cards) || cards.length === 0) {
      return initial;
    }
    const replenished = this.replenishDeck(meta, key, cards);
    return this.drawCard<T>(replenished, key);
  }

  replenishDeck<T = string>(
    meta: PanierExpressMetadata,
    key: string,
    cards: T[],
  ): PanierExpressMetadata {
    const metaRng = this.random.createMetaRng(meta as any);
    const pool = this.deckPool.set<T>(
      meta.decks as DeckPoolState<T>,
      key,
      this.deckPool.shuffle([...cards], metaRng.rng),
    );
    return {
      ...metaRng.getMeta(),
      decks: pool as PanierExpressDeckPool,
    };
  }
}

import { Injectable } from '@nestjs/common';
import { GameCoreService } from '../../../../core/services/game-core.service';
import { GameStateEntity } from '../../../../core/entities/game-state.entity';
import { PanierExpressMetadata } from '../model/panier-express-state.entity';
import { PanierExpressSetupService } from '../setup/panier-express-setup.service';
import { playingLog } from '../../../../../common/utils/playing-logger';
import { PanierExpressUtils } from '../model/panier-express-utils.service';
import { PanierExpressDeckService } from './panier-express-deck.service';

@Injectable()
export class PanierExpressDrawService {
  private static readonly MAX_INVENTORY = 5;

  constructor(
    private readonly setup: PanierExpressSetupService,
    private readonly core: GameCoreService,
    private readonly utils: PanierExpressUtils,
    private readonly deckHelper: PanierExpressDeckService,
  ) {}

  drawCourse(
    state: GameStateEntity,
    playerId: number,
    standId?: string,
  ): GameStateEntity {
    const meta = state.metadata as PanierExpressMetadata;
    const noDraw = (meta as any)?.statuses?.noDrawCourses?.[playerId] ?? 0;
    if (noDraw > 0) {
      return this.core.appendLog(
        state,
        `[Panier Express] ${this.utils.playerName(state, playerId)} ne peut pas piocher de carte ce tour-ci.`,
      );
    }
    const decks = meta.decks ?? this.setup.buildDeckPool(state);
    let metaAfter: PanierExpressMetadata = { ...meta, decks };

    const resolvedStandId = standId ?? this.findStandAtPosition(meta, playerId);
    const standKey = resolvedStandId ? `courses-${resolvedStandId}` : 'courses';

    const draw = this.drawAtStand(metaAfter, standKey, resolvedStandId);
    metaAfter = draw.metadata;
    if (!draw.card) {
      const debugLabel = resolvedStandId ? standKey : 'courses';
      return this.core.appendLog(
        state,
        `[Panier Express] Stand ${resolvedStandId || 'inconnu'} : aucune carte disponible (deck ${debugLabel}).`,
      );
    }

    const { card, metadata } = draw;
    let discarded: 'duplicate' | 'full' | null = null;
    let duplicateSource: 'panier' | 'inventaire' | null = null;
    let kept = false;
    const players = (state.players ?? []).map((player) => {
      if (player.id !== playerId) return player;
      const shoppingList = this.utils.toStringArray(player.shoppingList);
      const basket = this.utils.toStringArray(player.basket);
      const inventory = this.utils.toStringArray(player.inventory);
      const alreadyInBasket = basket.includes(card);
      const alreadyInInventory = inventory.includes(card);
      const isNeeded = shoppingList.includes(card) && !alreadyInBasket;

      if (alreadyInBasket) {
        discarded = 'duplicate';
        duplicateSource = 'panier';
        return { ...player, inventory, basket };
      }

      if (isNeeded) {
        kept = true;
        if (alreadyInInventory) {
          discarded = 'duplicate';
          duplicateSource = 'inventaire';
          return {
            ...player,
            basket: [...basket, card],
            inventory: this.utils.removeOne(inventory, card),
          };
        }
        return { ...player, basket: [...basket, card], inventory };
      }

      if (alreadyInInventory) {
        discarded = 'duplicate';
        duplicateSource = 'inventaire';
        return { ...player, inventory, basket };
      }
      if (inventory.length >= PanierExpressDrawService.MAX_INVENTORY) {
        discarded = 'full';
        return { ...player, inventory, basket };
      }
      kept = true;
      return { ...player, inventory: [...inventory, card], basket };
    });

    const nextMeta: PanierExpressMetadata = {
      ...(metadata as any),
      lastObtainedCourse: {
        ...(((metadata as any)?.lastObtainedCourse ?? {}) as Record<
          number,
          string | null
        >),
        [playerId]: kept ? card : null,
      },
      discards:
        discarded && card
          ? {
              ...((metadata as any)?.discards ?? {}),
              courses: [
                ...((((metadata as any)?.discards?.courses ?? []) as any[]) ??
                  []),
                card,
              ],
            }
          : ((metadata as any)?.discards ?? { courses: [] }),
    };
    const nextState: GameStateEntity = {
      ...state,
      players,
      metadata: nextMeta as any,
    };
    const courseLabel = this.utils.formatCourseLabel(card);
    const playerLabel = this.utils.playerName(state, playerId);
    const message = discarded
      ? discarded === 'duplicate'
        ? duplicateSource === 'panier'
          ? `[Panier Express] ${playerLabel} pioche "${courseLabel}" mais l'a déjà dans le panier. Cet ingrédient part donc à la défausse.`
          : duplicateSource === 'inventaire'
            ? `[Panier Express] ${playerLabel} pioche "${courseLabel}" mais l'a déjà dans l'inventaire. Cet ingrédient part donc à la défausse.`
            : `[Panier Express] ${playerLabel} pioche "${courseLabel}" mais l'a déjà. Cet ingrédient part donc à la défausse.`
        : `[Panier Express] ${playerLabel} pioche "${courseLabel}" mais l'inventaire est plein. Cet ingrédient part donc à la défausse.`
      : `[Panier Express] ${playerLabel} pioche "${courseLabel}".`;
    const logged = this.core.appendLog(nextState, message);

    const playerView = players.find((p) => p.id === playerId);
    playingLog('panier.draw', {
      roomId: (state.metadata as any)?.roomId ?? null,
      gameType: (state.metadata as any)?.gameType ?? null,
      userId: playerId,
      type: 'draw',
      playerId,
      card,
      standId: resolvedStandId || null,
      shoppingList: playerView?.shoppingList ?? [],
      basket: playerView?.basket ?? [],
      inventory: playerView?.inventory ?? [],
      discarded,
    });

    return logged;
  }

  private drawAtStand(
    meta: PanierExpressMetadata,
    standKey: string,
    standId?: string,
  ): { card: string | null; metadata: PanierExpressMetadata } {
    if (standId) {
      const replenish = () =>
        this.setup.buildReplenishableDeck(
          this.setup.standCourseMap()[standId] ?? this.setup.courseItems(),
        );
      const draw = this.deckHelper.drawWithReplenish<string>(
        meta,
        standKey,
        replenish,
      );
      if (draw.card) {
        return draw;
      }
      return this.deckHelper.drawWithReplenish<string>(
        draw.metadata,
        'courses',
        () => this.setup.buildReplenishableDeck(),
      );
    }
    return this.deckHelper.drawWithReplenish<string>(meta, 'courses', () =>
      this.setup.buildReplenishableDeck(),
    );
  }

  private findStandAtPosition(
    meta: PanierExpressMetadata,
    playerId: number,
  ): string | undefined {
    const pos = meta.positions?.[playerId] ?? 0;
    const tile = meta.tiles?.[pos];
    return tile?.type === 'stand' ? tile.standId : undefined;
  }
}

import { Injectable } from '@nestjs/common';
import { GameCoreService } from '../../../../core/services/game-core.service';
import type { GameStateEntity } from '../../../../core/entities/game-state.entity';
import { playingLog } from '../../../../../common/utils/playing-logger';
import type { PanierExpressMetadata } from '../model/panier-express-state.entity';
import { PanierExpressUtils } from '../model/panier-express-utils.service';
import { PanierExpressDeckService } from './panier-express-deck.service';
import type { InteractiveExchangeAdapter } from '../../../../modules/exchange/model/interactive-exchange.model';
import { defaultExchangeTargets } from '../../../../modules/exchange/model/interactive-exchange.model';
import { InteractiveExchangeService } from '../../../../modules/exchange/services/interactive-exchange.service';
import { PanierExpressSetupService } from '../setup/panier-express-setup.service';
import { RandomService } from '../../../../modules/random/services/random.service';

@Injectable()
export class PanierExpressExchangeService {
  constructor(
    private readonly core: GameCoreService,
    private readonly utils: PanierExpressUtils,
    private readonly deckHelper: PanierExpressDeckService,
    private readonly exchangeFlow: InteractiveExchangeService,
    private readonly setup: PanierExpressSetupService,
    private readonly random: RandomService,
  ) {}

  applyExchange(state: GameStateEntity, playerId: number): GameStateEntity {
    if (state.pending) {
      return this.core.appendLog(
        state,
        `[Panier Express] Un autre événement est déjà en attente.`,
      );
    }
    return this.requestExchange(state, playerId);
  }

  chooseTarget(
    state: GameStateEntity,
    playerId: number,
    targetPlayerId: number,
  ): GameStateEntity {
    const result = this.exchangeFlow.chooseTarget(
      state,
      playerId,
      targetPlayerId,
      this.adapter(),
    );
    if (result.kind === 'updated') return result.state;
    return this.core.appendLog(
      state,
      "[Panier Express] Cible d'échange invalide.",
    );
  }

  chooseGive(
    state: GameStateEntity,
    playerId: number,
    give: string,
  ): GameStateEntity {
    const result = this.exchangeFlow.chooseGive(
      state,
      playerId,
      give,
      this.adapter(),
    );
    if (result.kind !== 'offered') {
      return this.core.appendLog(state, '[Panier Express] Échange invalide.');
    }

    const offer = result.offer;
    const giveLabel = this.utils.formatCourseLabel(offer.give);
    const takeLabel =
      offer.take != null ? this.utils.formatCourseLabel(offer.take) : null;
    const takeText = takeLabel != null ? `"${takeLabel}"` : 'aucune carte';
    return this.core.appendLog(
      result.state,
      `[Panier Express] ${offer.initiatorUsername} propose un échange à ${offer.targetUsername} : il donne "${giveLabel}" et recevra ${takeText}.`,
    );
  }

  acceptOffer(state: GameStateEntity, targetPlayerId: number): GameStateEntity {
    const result = this.exchangeFlow.acceptOffer(
      state,
      targetPlayerId,
      this.adapter(),
    );
    if (result.kind !== 'resolved') {
      return this.core.appendLog(
        state,
        "[Panier Express] Acceptation d'échange invalide.",
      );
    }

    const offer = result.offer;
    const giveLabel = this.utils.formatCourseLabel(offer.give);
    const takeLabel =
      offer.take != null ? this.utils.formatCourseLabel(offer.take) : null;
    if (offer.bonusRequested) {
      const after = this.core.appendLog(
        result.state,
        `[Panier Express] Échange accepté : ${offer.initiatorUsername} donne "${giveLabel}" à ${offer.targetUsername}. ${offer.targetUsername} n'a aucune carte et perd 2 tours.`,
      );
      return {
        ...after,
        pending: {
          type: 'draw',
          playerId: offer.initiatorPlayerId,
          blocking: true,
          label: 'Piocher une course bonus (Espace).',
          data: {
            kind: 'queue',
            queue: [{ playerId: offer.initiatorPlayerId, standId: 'bonus' }],
            cursor: 0,
          },
        },
      } as any;
    }

    playingLog('panier.exchange.resolve', {
      roomId: (state.metadata as any)?.roomId ?? null,
      gameType: (state.metadata as any)?.gameType ?? null,
      userId: offer.initiatorPlayerId,
      type: 'exchange_resolve',
      playerId: offer.initiatorPlayerId,
      targetPlayerId: offer.targetPlayerId,
    });

    return this.core.appendLog(
      result.state,
      `[Panier Express] Échange accepté : ${offer.initiatorUsername} donne "${giveLabel}" et reçoit "${takeLabel ?? ''}" de ${offer.targetUsername}.`,
    );
  }

  refuseOffer(state: GameStateEntity, targetPlayerId: number): GameStateEntity {
    const pending = state.pending as any;
    const offer =
      pending && pending.type === 'exchange' && pending.step === 'confirm'
        ? pending
        : null;
    const cleared = this.exchangeFlow.refuseOffer(state, targetPlayerId);
    if (!offer) {
      return this.core.appendLog(
        state,
        "[Panier Express] Refus d'échange invalide.",
      );
    }
    return this.core.appendLog(
      cleared,
      `[Panier Express] ${offer.targetUsername} refuse l'échange proposé par ${offer.initiatorUsername}.`,
    );
  }

  applyExchangeCard(
    state: GameStateEntity,
    initiatorPlayerId: number,
    targetPlayerId: number,
    card: string,
  ): GameStateEntity {
    const kind = String(card ?? '').trim();
    if (!kind) return state;

    if (kind === 'vol-discret') {
      const meta = (state.metadata ?? {}) as any;
      const target = (state.players ?? []).find(
        (p) => p.id === targetPlayerId,
      ) as any;
      const inv = this.utils.toStringArray(target?.inventory);
      if (!inv.length) {
        return this.core.appendLog(
          state,
          `[Panier Express] Vol discret : ${this.utils.playerName(state, targetPlayerId)} n'a aucune carte.`,
        );
      }
      const metaRng = this.random.createMetaRng(meta);
      const picked = this.random.pickOne(metaRng.getMeta(), inv);
      const stolen = String(picked.value ?? '').trim();
      if (!stolen) return state;

      let next: GameStateEntity = { ...state, metadata: picked.meta };
      next = removeFromInventoryState(this.utils, next, targetPlayerId, stolen);
      next = addCardToPlayerState(this.utils, next, initiatorPlayerId, stolen);

      return this.core.appendLog(
        next,
        `[Panier Express] Vol discret : ${this.utils.playerName(
          state,
          initiatorPlayerId,
        )} vole "${stolen}" à ${this.utils.playerName(state, targetPlayerId)}.`,
      );
    }

    if (kind === 'chariot-echange') {
      const initiator = (state.players ?? []).find(
        (p) => p.id === initiatorPlayerId,
      ) as any;
      const target = (state.players ?? []).find(
        (p) => p.id === targetPlayerId,
      ) as any;
      const initiatorInv = this.utils.toStringArray(initiator?.inventory);
      const targetInv = this.utils.toStringArray(target?.inventory);
      let next: GameStateEntity = state;
      next = setInventoryState(this.utils, next, initiatorPlayerId, []);
      next = setInventoryState(this.utils, next, targetPlayerId, []);
      targetInv.forEach((card) => {
        next = addCardToPlayerState(this.utils, next, initiatorPlayerId, card);
      });
      initiatorInv.forEach((card) => {
        next = addCardToPlayerState(this.utils, next, targetPlayerId, card);
      });
      return this.core.appendLog(
        next,
        `[Panier Express] Chariot échangé : ${this.utils.playerName(
          state,
          initiatorPlayerId,
        )} échange son inventaire avec ${this.utils.playerName(state, targetPlayerId)}.`,
      );
    }

    if (kind === 'echange-force') {
      const initiator = (state.players ?? []).find(
        (p) => p.id === initiatorPlayerId,
      ) as any;
      const target = (state.players ?? []).find(
        (p) => p.id === targetPlayerId,
      ) as any;
      const initiatorInv = this.utils.toStringArray(initiator?.inventory);
      const targetInv = this.utils.toStringArray(target?.inventory);
      if (!initiatorInv.length || !targetInv.length) {
        return this.core.appendLog(
          state,
          `[Panier Express] Échange forcé : inventaire vide.`,
        );
      }

      let next: GameStateEntity = state;
      const metaRng = this.random.createMetaRng((next.metadata as any) ?? {});
      const pickA = this.random.pickOne(metaRng.getMeta(), initiatorInv);
      next = { ...next, metadata: pickA.meta };
      const aCard = String(pickA.value ?? '').trim();
      const pickB = this.random.pickOne(
        (next.metadata as any) ?? {},
        targetInv,
      );
      next = { ...next, metadata: pickB.meta };
      const bCard = String(pickB.value ?? '').trim();

      if (aCard)
        next = removeFromInventoryState(
          this.utils,
          next,
          initiatorPlayerId,
          aCard,
        );
      if (bCard)
        next = removeFromInventoryState(
          this.utils,
          next,
          targetPlayerId,
          bCard,
        );
      if (aCard)
        next = addCardToPlayerState(this.utils, next, targetPlayerId, aCard);
      if (bCard)
        next = addCardToPlayerState(this.utils, next, initiatorPlayerId, bCard);

      return this.core.appendLog(
        next,
        `[Panier Express] Échange forcé : échange au hasard entre ${this.utils.playerName(
          state,
          initiatorPlayerId,
        )} et ${this.utils.playerName(state, targetPlayerId)}.`,
      );
    }

    if (kind === 'echange-impose') {
      const target = (state.players ?? []).find(
        (p) => p.id === targetPlayerId,
      ) as any;
      const inv = this.utils.toStringArray(target?.inventory);
      if (!inv.length) {
        return this.core.appendLog(
          state,
          `[Panier Express] Échange imposé : ${this.utils.playerName(state, targetPlayerId)} n'a aucune carte.`,
        );
      }
      return {
        ...state,
        pending: {
          type: 'pick',
          playerId: targetPlayerId,
          blocking: true,
          label: `Choisissez une carte à donner à ${this.utils.playerName(
            state,
            initiatorPlayerId,
          )}, puis Entrée.`,
          choices: inv,
          data: {
            kind: 'exchange.impose.choose_card',
            initiatorId: initiatorPlayerId,
            cards: inv,
          },
        } as any,
      };
    }

    return this.core.appendLog(
      state,
      `[Panier Express] Carte d'échange non gérée : ${kind}.`,
    );
  }

  private requestExchange(
    state: GameStateEntity,
    playerId: number,
  ): GameStateEntity {
    const meta = state.metadata as PanierExpressMetadata;
    if (!meta.decks) {
      return this.core.appendLog(
        state,
        '[Panier Express] Decks indisponibles pour les échanges.',
      );
    }

    const draw = this.deckHelper.drawWithReplenish<string>(
      meta,
      'exchanges',
      () => this.setup.exchangeCards(),
    );
    const metadata = draw.metadata;
    const resolvedCard = draw.card ?? 'exchange';

    // Certaines cartes d'échange ont des effets directs / choix spécifiques.
    // On utilise `pending: pick` pour les cartes nécessitant un choix simple, sinon fallback sur l'échange interactif.
    if (
      [
        'vol-discret',
        'chariot-echange',
        'echange-impose',
        'echange-force',
      ].includes(resolvedCard)
    ) {
      const targets = (state.players ?? [])
        .filter((p) => p.id !== playerId)
        .map((p) => ({ playerId: p.id, username: p.username }));
      const choices = targets
        .map((t) => String(t.username ?? ''))
        .filter((v) => v.length > 0);
      if (!choices.length) {
        return this.core.appendLog(
          { ...state, metadata },
          `[Panier Express] Aucun joueur disponible pour ${resolvedCard}.`,
        );
      }
      const exchangeLabel =
        this.utils.formatEventLabel(resolvedCard) || resolvedCard;
      return {
        ...state,
        metadata,
        pending: {
          type: 'pick',
          playerId,
          blocking: true,
          label: `Choisissez un joueur pour ${exchangeLabel}, puis Entrée.`,
          choices,
          data: { kind: 'exchange.choose_target', card: resolvedCard, targets },
        } as any,
      };
    }

    if (resolvedCard === 'troc-rapide') {
      const players = state.players ?? [];
      if (players.length < 2) {
        return this.core.appendLog(
          { ...state, metadata },
          `[Panier Express] Troc rapide : aucun joueur disponible.`,
        );
      }
      const idx = players.findIndex((p) => p.id === playerId);
      const targetPlayerId = Number(
        players[(idx - 1 + players.length) % players.length]?.id,
      );
      const me = (state.players ?? []).find((p) => p.id === playerId) as any;
      const inv = this.utils.toStringArray(me?.inventory);
      if (!inv.length) {
        return this.core.appendLog(
          { ...state, metadata },
          `[Panier Express] Troc rapide : inventaire vide.`,
        );
      }
      return {
        ...state,
        metadata,
        pending: {
          type: 'pick',
          playerId,
          blocking: true,
          label: `Choisissez une carte à échanger avec ${this.utils.playerName(state, targetPlayerId)}, puis Entrée.`,
          choices: inv,
          data: { kind: 'exchange.troc_rapide.choose_give', targetPlayerId },
        } as any,
      };
    }

    if (resolvedCard === 'troc-fruit-legume') {
      const targets = (state.players ?? [])
        .filter((p) => p.id !== playerId)
        .map((p) => ({ playerId: p.id, username: p.username }));
      const choices = targets
        .map((t) => String(t.username ?? ''))
        .filter((v) => v.length > 0);
      if (!choices.length) {
        return this.core.appendLog(
          { ...state, metadata },
          `[Panier Express] Troc fruit/l?gume : aucun joueur disponible.`,
        );
      }
      return {
        ...state,
        metadata,
        pending: {
          type: 'pick',
          playerId,
          blocking: true,
          label: 'Choisissez un joueur pour le troc, puis Entrée.',
          choices,
          data: { kind: 'exchange.troc_fruit_legume.choose_target', targets },
        } as any,
      };
    }

    if (resolvedCard === 'echange-saison') {
      const targets = (state.players ?? [])
        .filter((p) => p.id !== playerId)
        .map((p) => ({ playerId: p.id, username: p.username }));
      const choices = targets
        .map((t) => String(t.username ?? ''))
        .filter((v) => v.length > 0);
      if (!choices.length) {
        return this.core.appendLog(
          { ...state, metadata },
          `[Panier Express] Échange de saison : aucun joueur disponible.`,
        );
      }
      return {
        ...state,
        metadata,
        pending: {
          type: 'pick',
          playerId,
          blocking: true,
          label: 'Choisissez un joueur pour l’échange de saison, puis Entrée.',
          choices,
          data: { kind: 'exchange.echange_saison.choose_target', targets },
        } as any,
      };
    }

    if (resolvedCard === 'echange-strategique') {
      const targets = (state.players ?? [])
        .filter((p) => p.id !== playerId)
        .map((p) => ({ playerId: p.id, username: p.username }));
      const choices = targets
        .map((t) => String(t.username ?? ''))
        .filter((v) => v.length > 0);
      if (!choices.length) {
        return this.core.appendLog(
          { ...state, metadata },
          `[Panier Express] Échange stratégique : aucun joueur disponible.`,
        );
      }

      const exchangeIdOut = this.random.nextInt(metadata as any, 1_000_000_000);
      const nextMetadata = exchangeIdOut.meta;
      const exchangeId = exchangeIdOut.value;

      return {
        ...state,
        metadata: nextMetadata,
        pending: {
          type: 'pick',
          playerId,
          blocking: true,
          label:
            "Choisissez un joueur pour l'échange stratégique, puis Entrée.",
          choices,
          data: {
            kind: 'exchange.strategique.choose_target',
            exchangeId,
            targets,
          },
        } as any,
      };
    }

    if (resolvedCard === 'marche-noir') {
      const me = (state.players ?? []).find((p) => p.id === playerId) as any;
      const cards = this.utils.toStringArray(me?.inventory);
      if (!cards.length) {
        return this.core.appendLog(
          { ...state, metadata },
          `[Panier Express] Marché noir : aucune carte à défausser.`,
        );
      }
      return {
        ...state,
        metadata,
        pending: {
          type: 'pick',
          playerId,
          blocking: true,
          label: 'Choisissez une carte à défausser, puis Entrée.',
          choices: cards,
          data: { kind: 'exchange.marche_noir.discard' },
        } as any,
      };
    }

    if (
      resolvedCard === 'echange-devant' ||
      resolvedCard === 'echange-derriere'
    ) {
      const exchangeLabel = this.utils.formatEventLabel(resolvedCard);
      const players = state.players ?? [];
      if (players.length < 2) {
        return this.core.appendLog(
          { ...state, metadata },
          `[Panier Express] ${exchangeLabel} : aucun joueur disponible.`,
        );
      }
      const idx = players.findIndex((p) => p.id === playerId);
      const targetPlayerId = Number(
        players[
          resolvedCard === 'echange-devant'
            ? (idx + 1) % players.length
            : (idx - 1 + players.length) % players.length
        ]?.id,
      );
      const me = (state.players ?? []).find((p) => p.id === playerId) as any;
      const target = (state.players ?? []).find(
        (p) => p.id === targetPlayerId,
      ) as any;
      const myInv = this.utils.toStringArray(me?.inventory);
      const theirInv = this.utils.toStringArray(target?.inventory);
      if (!myInv.length || !theirInv.length) {
        return this.core.appendLog(
          { ...state, metadata },
          `[Panier Express] ${exchangeLabel} : inventaire vide.`,
        );
      }
      let next: GameStateEntity = { ...state, metadata };
      const metaRng = this.random.createMetaRng((next.metadata as any) ?? {});
      const pickA = this.random.pickOne(metaRng.getMeta(), myInv);
      next = { ...next, metadata: pickA.meta };
      const aCard = String(pickA.value ?? '').trim();
      const pickB = this.random.pickOne((next.metadata as any) ?? {}, theirInv);
      next = { ...next, metadata: pickB.meta };
      const bCard = String(pickB.value ?? '').trim();
      if (aCard)
        next = removeFromInventoryState(this.utils, next, playerId, aCard);
      if (bCard)
        next = removeFromInventoryState(
          this.utils,
          next,
          targetPlayerId,
          bCard,
        );
      if (aCard)
        next = addCardToPlayerState(this.utils, next, targetPlayerId, aCard);
      if (bCard) next = addCardToPlayerState(this.utils, next, playerId, bCard);
      const positionLabel =
        resolvedCard === 'echange-devant'
          ? 'juste devant vous'
          : 'juste derrière vous';
      return this.core.appendLog(
        next,
        `[Panier Express] ${exchangeLabel} : échange au hasard avec le joueur ${positionLabel} (${this.utils.playerName(state, targetPlayerId)}).`,
      );
    }

    if (resolvedCard === 'panier-mixe') {
      const metaAny = metadata as any;
      const positions = (metaAny.positions ?? {}) as Record<number, number>;
      const tiles = Array.isArray(metaAny.tiles) ? metaAny.tiles : [];
      const total = tiles.length || 1;
      const others = (state.players ?? []).filter((p) => p.id !== playerId);
      if (!others.length) {
        return this.core.appendLog(
          { ...state, metadata },
          `[Panier Express] Panier mixé : aucun joueur disponible.`,
        );
      }
      const mePos = positions[playerId] ?? 0;
      let targetPlayerId = others[0].id;
      let bestDist = Number.POSITIVE_INFINITY;
      others.forEach((p) => {
        const pos = positions[p.id] ?? 0;
        const forward = (pos - mePos + total) % total;
        const backward = (mePos - pos + total) % total;
        const dist = Math.min(forward, backward);
        if (dist < bestDist) {
          bestDist = dist;
          targetPlayerId = p.id;
        }
      });
      const me = (state.players ?? []).find((p) => p.id === playerId) as any;
      const target = (state.players ?? []).find(
        (p) => p.id === targetPlayerId,
      ) as any;
      const aInv = this.utils.toStringArray(me?.inventory);
      const bInv = this.utils.toStringArray(target?.inventory);
      const combined = [...aInv, ...bInv];
      if (!combined.length) {
        return this.core.appendLog(
          { ...state, metadata },
          `[Panier Express] Panier mixé : aucun inventaire à mélanger.`,
        );
      }
      const shuffled = this.random.shuffle((metadata as any) ?? {}, combined);
      let next: GameStateEntity = { ...state, metadata: shuffled.meta };
      next = setInventoryState(this.utils, next, playerId, []);
      next = setInventoryState(this.utils, next, targetPlayerId, []);

      const half = Math.floor(shuffled.values.length / 2);
      const aCards = shuffled.values.slice(0, half);
      const bCards = shuffled.values.slice(half, half * 2);
      const leftover = shuffled.values.slice(half * 2);

      aCards.forEach((c) => {
        next = addCardToPlayerState(this.utils, next, playerId, c);
      });
      bCards.forEach((c) => {
        next = addCardToPlayerState(this.utils, next, targetPlayerId, c);
      });
      leftover.forEach((c) => {
        next = addToDiscardState(next, c);
      });

      return this.core.appendLog(
        next,
        `[Panier Express] Panier mixé : mélange avec ${this.utils.playerName(state, targetPlayerId)}.`,
      );
    }

    if (resolvedCard === 'echange-masque') {
      const eligible = (state.players ?? []).filter(
        (p: any) => this.utils.toStringArray(p.inventory).length > 0,
      );
      if (eligible.length < 2) {
        return this.core.appendLog(
          { ...state, metadata },
          `[Panier Express] Échange masqué : pas assez de joueurs avec des cartes.`,
        );
      }
      const shuffledPlayers = this.random.shuffle(
        (metadata as any) ?? {},
        eligible.map((p) => p.id),
      );
      let next: GameStateEntity = {
        ...state,
        metadata: shuffledPlayers.meta,
      };
      const pickedByPlayer: Record<number, string> = {};
      for (const pid of shuffledPlayers.values) {
        const inv = this.utils.toStringArray(
          (next.players ?? []).find((p: any) => p.id === pid)?.inventory,
        );
        const pick = this.random.pickOne((next.metadata as any) ?? {}, inv);
        next = { ...next, metadata: pick.meta };
        const card = String(pick.value ?? '').trim();
        if (!card) continue;
        pickedByPlayer[pid] = card;
        next = removeFromInventoryState(this.utils, next, pid, card);
      }
      const ids = shuffledPlayers.values;
      for (let i = 0; i < ids.length; i += 1) {
        const giverId = ids[i];
        const receiverId = ids[(i + 1) % ids.length];
        const card = pickedByPlayer[giverId];
        if (card) {
          next = addCardToPlayerState(this.utils, next, receiverId, card);
        }
      }
      return this.core.appendLog(
        next,
        `[Panier Express] Échange masqué : échange réalisé.`,
      );
    }

    if (resolvedCard === 'panier-collectif') {
      const players = state.players ?? [];
      const contributors: number[] = [];
      let pot: string[] = [];
      let next: GameStateEntity = { ...state, metadata };

      for (const p of players) {
        const inv = this.utils.toStringArray((p as any).inventory);
        if (!inv.length) continue;
        const pick = this.random.pickOne((next.metadata as any) ?? {}, inv);
        next = { ...next, metadata: pick.meta };
        const card = String(pick.value ?? '').trim();
        if (!card) continue;
        contributors.push(p.id);
        pot.push(card);
        next = removeFromInventoryState(this.utils, next, p.id, card);
      }
      if (!pot.length || contributors.length < 2) {
        return this.core.appendLog(
          next,
          `[Panier Express] Inventaire collectif : pas assez de cartes dans le pot.`,
        );
      }
      const shuffledPot = this.random.shuffle(
        (next.metadata as any) ?? {},
        pot,
      );
      next = { ...next, metadata: shuffledPot.meta };
      pot = shuffledPot.values;
      for (let i = 0; i < contributors.length; i += 1) {
        next = addCardToPlayerState(this.utils, next, contributors[i], pot[i]);
      }
      return this.core.appendLog(
        next,
        `[Panier Express] Inventaire collectif : redistribution d'inventaire effectuée.`,
      );
    }

    if (resolvedCard === 'echange-simultane') {
      const players = state.players ?? [];
      if (players.length < 2) {
        return this.core.appendLog(
          { ...state, metadata },
          `[Panier Express] Échange simultané : aucun joueur disponible.`,
        );
      }
      let next: GameStateEntity = { ...state, metadata };
      const toPass: Array<{ from: number; card: string }> = [];
      for (const p of players) {
        const inv = this.utils.toStringArray((p as any).inventory);
        if (!inv.length) continue;
        const pick = this.random.pickOne((next.metadata as any) ?? {}, inv);
        next = { ...next, metadata: pick.meta };
        const card = String(pick.value ?? '').trim();
        if (!card) continue;
        toPass.push({ from: p.id, card });
        next = removeFromInventoryState(this.utils, next, p.id, card);
      }
      for (const entry of toPass) {
        const idx = players.findIndex((p) => p.id === entry.from);
        const targetId = players[(idx + 1) % players.length].id;
        next = addCardToPlayerState(this.utils, next, targetId, entry.card);
      }
      for (const entry of toPass) {
        const idx = players.findIndex((p) => p.id === entry.from);
        const targetId = players[(idx + 1) % players.length].id;
        next = this.core.appendLog(
          next,
          `[Panier Express] Échange simultané : ${this.utils.playerName(
            state,
            entry.from,
          )} donne "${this.utils.formatCourseLabel(
            entry.card,
          )}" à ${this.utils.playerName(state, targetId)}.`,
        );
      }
      return next;
    }

    if (resolvedCard === 'defausse-aleatoire') {
      const inventory = this.utils.toStringArray(
        (state.players ?? []).find((p) => p.id === playerId)?.inventory,
      );
      if (!inventory.length) {
        return this.core.appendLog(
          { ...state, metadata },
          `[Panier Express] Défausse aléatoire : inventaire vide.`,
        );
      }
      const metaRng = this.random.createMetaRng(metadata as any);
      const picked = this.random.pickOne(metaRng.getMeta(), inventory);
      const card = String(picked.value ?? '').trim();
      const updatedMeta = picked.meta;
      const players = (state.players ?? []).map((p: any) => {
        if (p.id !== playerId) return p;
        const nextInv = this.utils.removeOne(inventory, card);
        return { ...p, inventory: nextInv };
      });
      const cardLabel = this.utils.formatCourseLabel(card);
      return this.core.appendLog(
        addToDiscardState({ ...state, players, metadata: updatedMeta }, card),
        `[Panier Express] Défausse aléatoire : ${this.utils.playerName(state, playerId)} défausse "${cardLabel}".`,
      );
    }

    const started = this.exchangeFlow.start(
      { ...state, metadata },
      playerId,
      resolvedCard,
      this.adapter(),
    );

    if (started.kind === 'started') {
      const pending = started.pending as any;
      const targetsCount = Array.isArray(pending?.targets)
        ? pending.targets.length
        : 0;
      playingLog('panier.exchange.pending', {
        roomId: (state.metadata as any)?.roomId ?? null,
        gameType: (state.metadata as any)?.gameType ?? null,
        userId: playerId,
        type: 'exchange_pending',
        playerId,
        card: resolvedCard,
        targets: targetsCount,
      });
      return started.state;
    }

    const reason =
      started.kind === 'no_targets'
        ? `[Panier Express] Aucun joueur disponible pour un échange (${resolvedCard}).`
        : `[Panier Express] Pas d'échange possible (${resolvedCard}).`;
    return this.core.appendLog({ ...state, metadata }, reason);
  }

  private adapter(): InteractiveExchangeAdapter {
    return {
      listTargets: defaultExchangeTargets,
      getInventory: (state, playerId) => {
        const player = (state.players ?? []).find(
          (p) => p.id === playerId,
        ) as any;
        return this.utils.toStringArray(player?.inventory);
      },
      removeFromInventory: (state, playerId, card) => {
        const players = (state.players ?? []).map((p: any) => {
          if (p.id !== playerId) return p;
          const inv = this.utils.toStringArray(p.inventory);
          return { ...p, inventory: removeOne(inv, card) };
        });
        return { ...state, players };
      },
      addCardToPlayer: (state, playerId, card) => {
        return addCardToPlayerState(this.utils, state, playerId, card);
      },
      setSkipTurns: (state, playerId, turns) =>
        setSkipTurns(state, playerId, turns),
    };
  }
}

function removeOne(collection: string[], value: string): string[] {
  const copy = [...collection];
  const idx = copy.findIndex((entry) => entry === value);
  if (idx >= 0) {
    copy.splice(idx, 1);
  }
  return copy;
}

function addCardToPlayer(
  utils: PanierExpressUtils,
  player: any,
  card: string,
): { player: any; kept: boolean; discarded: boolean } {
  const trimmed = String(card ?? '').trim();
  if (!trimmed || !player) {
    return { player, kept: false, discarded: false };
  }
  const list = utils.toStringArray(player.shoppingList);
  const basket = utils.toStringArray(player.basket);
  const inventory = utils.toStringArray(player.inventory);
  const alreadyInBasket = basket.includes(trimmed);
  const alreadyInInventory = inventory.includes(trimmed);
  const isNeeded = list.includes(trimmed) && !alreadyInBasket;

  // Pas de doublons: si déjà présent, on défausse la carte reçue.
  // Si la carte est nécessaire et déjà dans l'inventaire, on la transfère au panier.
  if (alreadyInBasket || alreadyInInventory) {
    if (isNeeded && alreadyInInventory) {
      return {
        player: {
          ...player,
          basket: [...basket, trimmed],
          inventory: utils.removeOne(inventory, trimmed),
        },
        kept: false,
        discarded: true,
      };
    }
    return {
      player: { ...player, basket, inventory },
      kept: false,
      discarded: true,
    };
  }

  if (isNeeded) {
    return {
      player: { ...player, basket: [...basket, trimmed], inventory },
      kept: true,
      discarded: false,
    };
  }

  if (inventory.length >= 5) {
    return {
      player: { ...player, basket, inventory },
      kept: false,
      discarded: true,
    };
  }

  return {
    player: { ...player, inventory: [trimmed, ...inventory], basket },
    kept: true,
    discarded: false,
  };
}

function addCardToPlayerState(
  utils: PanierExpressUtils,
  state: GameStateEntity,
  playerId: number,
  card: string,
): GameStateEntity {
  const trimmed = String(card ?? '').trim();
  if (!trimmed) return state;
  let kept = false;
  let discarded = false;
  const players = (state.players ?? []).map((p: any) => {
    if (p.id !== playerId) return p;
    const result = addCardToPlayer(utils, p, trimmed);
    kept = result.kept;
    discarded = result.discarded;
    return result.player;
  });
  const meta = (state.metadata ?? {}) as any;
  const currentDiscards = Array.isArray(meta?.discards?.courses)
    ? meta.discards.courses.map((v: any) => String(v))
    : [];
  return {
    ...state,
    players,
    metadata: {
      ...meta,
      lastObtainedCourse: {
        ...(meta?.lastObtainedCourse ?? {}),
        [playerId]: kept ? trimmed : null,
      },
      discards: {
        ...(meta?.discards ?? {}),
        courses: discarded ? [...currentDiscards, trimmed] : currentDiscards,
      },
    },
  };
}

function removeFromInventoryState(
  utils: PanierExpressUtils,
  state: GameStateEntity,
  playerId: number,
  card: string,
): GameStateEntity {
  const trimmed = String(card ?? '').trim();
  if (!trimmed) return state;
  const players = (state.players ?? []).map((p: any) => {
    if (p.id !== playerId) return p;
    const inv = utils.toStringArray(p.inventory);
    return { ...p, inventory: removeOne(inv, trimmed) };
  });
  return { ...state, players };
}

function setInventoryState(
  utils: PanierExpressUtils,
  state: GameStateEntity,
  playerId: number,
  inventory: string[],
): GameStateEntity {
  const nextInv = utils.toStringArray(inventory);
  const players = (state.players ?? []).map((p: any) => {
    if (p.id !== playerId) return p;
    return { ...p, inventory: nextInv };
  });
  return { ...state, players };
}

function addToDiscardState(
  state: GameStateEntity,
  card: string,
): GameStateEntity {
  const trimmed = String(card ?? '').trim();
  if (!trimmed) return state;
  const meta = (state.metadata ?? {}) as any;
  const current = Array.isArray(meta?.discards?.courses)
    ? meta.discards.courses.map((v: any) => String(v))
    : [];
  return {
    ...state,
    metadata: {
      ...meta,
      discards: {
        ...(meta?.discards ?? {}),
        courses: [...current, trimmed],
      },
    },
  };
}

function setSkipTurns(
  state: GameStateEntity,
  playerId: number,
  turns: number,
): GameStateEntity {
  const meta = (state.metadata ?? {}) as any;
  const current = meta?.statuses?.skipTurn?.[playerId] ?? 0;
  const nextCount = Math.max(current, Math.max(1, turns || 1));
  return {
    ...state,
    metadata: {
      ...meta,
      statuses: {
        ...(meta?.statuses ?? {}),
        skipTurn: {
          ...(meta?.statuses?.skipTurn ?? {}),
          [playerId]: nextCount,
        },
      },
    },
  };
}

import { Injectable } from '@nestjs/common';
import { GameCoreService } from '../../../../core/services/game-core.service';
import { GameStateEntity } from '../../../../core/entities/game-state.entity';
import {
  QuizRunnerService,
  QuizQuestion,
  QuizState,
} from '../../../../modules/quiz/services/quiz-runner.service';
import {
  DeckPoolService,
  DeckPoolState,
} from '../../../../modules/cards/services/deck-pool.service';
import { RandomService } from '../../../../modules/random/services/random.service';
import { sanitizeText } from '../../../../../common/utils/sanitize-text';
import {
  PanierExpressMetadata,
  PanierExpressDeckPool,
} from '../model/panier-express-state.entity';
import { PanierExpressUtils } from '../model/panier-express-utils.service';

@Injectable()
export class PanierExpressQuizService {
  constructor(
    private readonly deckPool: DeckPoolService,
    private readonly quizRunner: QuizRunnerService,
    private readonly core: GameCoreService,
    private readonly utils: PanierExpressUtils,
    private readonly random: RandomService,
  ) {}

  applyQuiz(state: GameStateEntity, playerId: number): GameStateEntity {
    const meta = state.metadata as PanierExpressMetadata;
    if (!meta.decks) {
      return this.core.appendLog(
        state,
        '[Panier Express] Quiz : deck indisponible.',
      );
    }
    const metaRng = this.random.createMetaRng(meta as any);
    const { card, pool } = this.deckPool.draw<QuizQuestion>(
      meta.decks as DeckPoolState<QuizQuestion>,
      'quizzes',
      metaRng.rng,
    );
    let metadata: any = {
      ...metaRng.getMeta(),
      decks: pool as PanierExpressDeckPool,
    };
    const quiz = card;
    if (!quiz) {
      return this.core.appendLog(
        state,
        '[Panier Express] Quiz : aucune carte disponible.',
      );
    }

    const question = sanitizeText(quiz.question);
    const answer = sanitizeText(String(quiz.answer ?? '')).trim();
    const rawChoices = Array.isArray(quiz.choices) ? quiz.choices : [];
    const unique = new Set<string>();
    const normalizedChoices: string[] = [];
    for (const choice of rawChoices) {
      const text = sanitizeText(String(choice)).trim();
      const key = text.toLowerCase();
      if (!text || unique.has(key)) continue;
      unique.add(key);
      normalizedChoices.push(text);
    }
    if (answer) {
      const key = answer.toLowerCase();
      if (!unique.has(key)) {
        unique.add(key);
        normalizedChoices.push(answer);
      }
    }
    const shuffled = this.random.shuffle(metadata, normalizedChoices);
    metadata = shuffled.meta;
    const choices = shuffled.values;

    const currentQuizState: QuizState = metadata.quiz ?? { pending: {} };
    const nextQuizState = this.quizRunner.setPending(
      currentQuizState,
      playerId,
      {
        id: quiz.id ?? `quiz-${playerId}`,
        question,
        answer,
        choices,
      },
    );

    const nextMeta: PanierExpressMetadata = {
      ...metadata,
      quiz: nextQuizState,
    };

    const next = { ...state, metadata: nextMeta };
    return this.core.appendLog(
      next,
      `Question pour ${this.utils.playerName(state, playerId)}: "${question}"`,
    );
  }
}

import { Injectable } from '@nestjs/common';
import type { GameSingleActionDto } from '../../../../engine/dto/game-action.dto';
import type { GameStateEntity } from '../../../../core/entities/game-state.entity';
import { BotRunnerService } from '../../../../modules/bot/services/bot-runner.service';
import { TurnStatusService } from '../../../../modules/turn/services/turn-status.service';
import { playingLog } from '../../../../../common/utils/playing-logger';
import type { PanierExpressMetadata } from '../model/panier-express-state.entity';
import * as PanierExpressRulebook from '../rulebook/rulebook';

@Injectable()
export class PanierExpressBotService {
  constructor(
    private readonly botRunner: BotRunnerService,
    private readonly turnStatus: TurnStatusService,
  ) {}

  getBotActions(
    state: GameStateEntity,
    meta: PanierExpressMetadata,
    botPlayerId: number,
  ): GameSingleActionDto[] {
    const current = state.turn?.currentPlayerId ?? null;
    const isBotTurn = current === botPlayerId;

    const profile = meta.botProfile ?? 'greedy';
    const skip = this.turnStatus.getStatus(state, botPlayerId, 'skipTurn');
    if (isBotTurn && skip > 0) {
      playingLog('panier.bot.skip', {
        roomId: (state.metadata as any)?.roomId ?? null,
        gameType: (state.metadata as any)?.gameType ?? null,
        userId: botPlayerId,
        type: 'skip_turn',
        botPlayerId,
        skip,
      });
      return [{ type: 'skip_turn', payload: { playerId: botPlayerId } }];
    }

    const available = this.injectQuizAnswer(
      PanierExpressRulebook.getAvailableActions(state, botPlayerId),
      meta,
      botPlayerId,
    );
    if (available.length === 0) return [];

    const rawPlayer = (state.players ?? []).find((p) => p.id === botPlayerId);
    const shoppingListRaw = rawPlayer?.shoppingList;
    const basketRaw = rawPlayer?.basket;
    const shoppingList = Array.isArray(shoppingListRaw) ? shoppingListRaw : [];
    const basket = Array.isArray(basketRaw) ? basketRaw : [];
    if (!Array.isArray(shoppingListRaw) || !Array.isArray(basketRaw)) {
      playingLog('panier.bot.warn', {
        roomId: (state.metadata as any)?.roomId ?? null,
        gameType: (state.metadata as any)?.gameType ?? null,
        userId: botPlayerId,
        type: 'warn',
        playerId: botPlayerId,
        shoppingListType: typeof shoppingListRaw,
        basketType: typeof basketRaw,
      });
    }
    const missing = new Set(
      shoppingList.filter((item) => !basket.includes(item)),
    );
    const players = state.players ?? [];
    const playerById = new Map<number, any>(players.map((p) => [p.id, p]));

    const score = (action: GameSingleActionDto) => {
      const type = action.type?.toLowerCase() ?? '';
      if (type === 'answer_quiz') return 6;
      if (type === 'pick_choice') {
        const index =
          typeof action.payload?.index === 'number' ? action.payload.index : 0;
        // Choix déterministe: on préfère les premiers items pour progresser.
        return 8 - Math.max(0, Math.min(6, index));
      }
      if (type === 'exchange_accept' || type === 'exchange_refuse') {
        const pending = state.pending as any;
        const offer =
          pending && pending.type === 'exchange' && pending.step === 'confirm'
            ? pending
            : null;
        if (!offer || offer.playerId !== botPlayerId) {
          return type === 'exchange_refuse' ? 1 : 0;
        }
        const give = String(offer.give ?? '').trim();
        const take = offer.take != null ? String(offer.take).trim() : null;
        const giveNeeded = give.length > 0 && missing.has(give);
        const takeNeeded = take != null && take.length > 0 && missing.has(take);
        const bonusRequested = offer.bonusRequested === true;

        // Si accepter fait perdre 2 tours (cible sans cartes), on préfère refuser.
        if (bonusRequested) {
          return type === 'exchange_refuse' ? 9 : -10;
        }

        if (type === 'exchange_accept') {
          return 5 + (giveNeeded ? 4 : 0) + (takeNeeded ? -4 : 1);
        }
        return 4 + (takeNeeded ? 3 : 0) + (giveNeeded ? -2 : 0);
      }
      if (type === 'exchange_choose_target') {
        const targetId = action.payload?.targetPlayerId;
        if (typeof targetId !== 'number') return 2;
        const target = playerById.get(targetId);
        const inv = Array.isArray(target?.inventory) ? target.inventory : [];
        const useful = inv.filter((c: any) => missing.has(String(c))).length;
        return 4 + useful * 2 + Math.min(2, inv.length / 3);
      }
      if (type === 'exchange_choose_give') {
        const give = action.payload?.give;
        if (typeof give !== 'string') return 2;
        const cost = missing.has(give) ? -2 : 1;
        return 4 + cost;
      }
      if (type === 'draw') return 7;
      if (type === 'roll') return 1;
      return 0;
    };

    const chosen = this.botRunner.choose(
      available,
      { state, playerId: botPlayerId },
      profile,
      {
        preferTypes: [
          'draw',
          'answer_quiz',
          'pick_choice',
          'exchange_choose_give',
          'exchange_choose_target',
          'roll',
        ],
        fallbackTypes: ['roll'],
        score,
      },
    );

    if (chosen.length === 0 && available.length > 0) {
      return [available[0]];
    }
    if (chosen.length) {
      playingLog('panier.bot.actions', {
        roomId: (state.metadata as any)?.roomId ?? null,
        gameType: (state.metadata as any)?.gameType ?? null,
        userId: botPlayerId,
        type: 'bot_actions',
        botPlayerId,
        actions: chosen.map((a) => a.type),
      });
    }
    return chosen;
  }

  private injectQuizAnswer(
    actions: GameSingleActionDto[],
    meta: PanierExpressMetadata,
    playerId: number,
  ): GameSingleActionDto[] {
    if (!Array.isArray(actions)) return [];
    const pending = meta.quiz?.pending?.[playerId];
    const choices = Array.isArray(pending?.choices) ? pending?.choices : [];
    if (!pending || !choices.length) return actions;
    // Déterministe (évite de dépendre de Math.random côté bot).
    const answer = choices[0];
    return actions.map((a) => {
      if (!a || (a.type || '').toLowerCase() !== 'answer_quiz') return a;
      return { ...a, payload: { ...(a.payload ?? {}), answer } };
    });
  }
}

import { GameStateEntity } from '../../../../core/entities/game-state.entity';
import { VictoryCondition } from '../../../../modules/victory/services/victory.service';

// Conditions de victoire declaratives pour Panier Express.
// Victoire des qu'un joueur complete sa liste dans son panier ET revient pile sur la case depart.
export const PANIER_EXPRESS_VICTORY: VictoryCondition[] = [
  {
    id: 'shopping-complete',
    description: 'Liste de courses complete + retour pile sur la case depart.',
    check: (state: GameStateEntity) => {
      const players = state.players ?? [];
      const positions =
        (state.metadata as any)?.positions &&
        typeof (state.metadata as any).positions === 'object'
          ? (state.metadata as any).positions
          : {};

      for (const player of players) {
        const shoppingList = Array.isArray((player as any).shoppingList)
          ? (player as any).shoppingList
          : [];
        const basket = Array.isArray((player as any).basket)
          ? (player as any).basket
          : [];
        const completed =
          shoppingList.length > 0 &&
          shoppingList.every((item) => basket.includes(item));

        const pos =
          typeof positions?.[player.id] === 'number'
            ? positions[player.id]
            : -1;
        const atStart = pos === 0;

        if (completed && atStart) {
          return {
            finished: true,
            winnerId: player.id,
            details: { basketSize: basket.length, position: pos },
          };
        }
      }

      return false;
    },
  },
];

import { Injectable } from '@nestjs/common';
import {
  GameStateEntity,
  PlayerStateEntity,
} from '../../../../core/entities/game-state.entity';
import { PanierExpressPlayer } from './panier-express-state.entity';

/**
 * Utilitaires partagés Panier Express.
 * Centralise les helpers liés aux joueurs pour éviter les accès non typés.
 */
@Injectable()
export class PanierExpressUtils {
  private static readonly COURSE_LABELS: Record<string, string> = {
    cepe: 'cèpe',
    'celeri-branche': 'céleri-branche',
    chataigne: 'châtaigne',
    clementine: 'clémentine',
    echalote: 'échalote',
    epinard: 'épinard',
    feve: 'fève',
    'jeune-pousse-d-ortie': "jeune pousse d'ortie",
    mais: 'maïs',
    mure: 'mûre',
    nefle: 'nèfle',
    patisson: 'pâtisson',
    peche: 'pêche',
    'pois-casse': 'pois cassés',
  };

  private static readonly EVENT_LABELS: Record<string, string> = {
    'produit-avarie': 'Produit avarié',
    'producteur-genereux': 'Producteur généreux',
    'troc-improvise': 'Troc improvisé',
  };

  playerName(state: GameStateEntity, playerId: number): string {
    const player = state.players?.find((p) => p.id === playerId);
    const username =
      typeof player?.username === 'string' ? player.username.trim() : '';
    return username.length ? username : `Joueur ${playerId}`;
  }

  getPlayerName(state: GameStateEntity, playerId: number): string {
    return this.playerName(state, playerId);
  }

  getPlayer(
    state: GameStateEntity,
    playerId: number,
  ): PanierExpressPlayer | null {
    const player = state.players?.find((p) => p.id === playerId);
    if (!player) return null;
    return this.normalizePlayer(player);
  }

  normalizePlayer(player: any): PanierExpressPlayer {
    return {
      id: player.id,
      username:
        typeof player.username === 'string'
          ? player.username
          : `Joueur ${player.id}`,
      isBot: player.isBot === true,
      shoppingList: this.toStringArray(player.shoppingList),
      basket: this.toStringArray(player.basket),
      inventory: this.toStringArray(player.inventory),
      pawn: typeof player.pawn === 'string' ? player.pawn : undefined,
    };
  }

  normalizePlayers(players: any[] | undefined): PanierExpressPlayer[] {
    if (!Array.isArray(players)) return [];
    return players.map((p) => this.normalizePlayer(p));
  }

  toStringArray(value: unknown): string[] {
    if (Array.isArray(value)) {
      return value
        .map((entry) => (entry == null ? '' : String(entry)))
        .filter((entry): entry is string => entry.length > 0);
    }

    if (typeof value === 'string') {
      try {
        const parsed = JSON.parse(value);
        if (Array.isArray(parsed)) {
          return parsed
            .map((entry) => (entry == null ? '' : String(entry)))
            .filter((entry): entry is string => entry.length > 0);
        }
      } catch {
        // ignore
      }

      return value
        .split(/[,;]+/)
        .map((v) => v.trim())
        .filter((v) => v.length > 0);
    }

    return [];
  }

  missingShoppingItems(
    player: PlayerStateEntity | null | undefined,
  ): Set<string> {
    if (!player) return new Set();
    const basket = Array.isArray(player.basket)
      ? player.basket.map((item) => String(item))
      : [];
    const shoppingList = this.toStringArray(player.shoppingList);
    return new Set(shoppingList.filter((item) => !basket.includes(item)));
  }

  getMissingItems(player: PanierExpressPlayer): Set<string> {
    return new Set(
      player.shoppingList.filter((item) => !player.basket.includes(item)),
    );
  }

  hasCompletedShopping(player: PanierExpressPlayer): boolean {
    return (
      player.shoppingList.length > 0 &&
      player.shoppingList.every((item) => player.basket.includes(item))
    );
  }

  isBot(player: any): boolean {
    const username = String(player?.username ?? '').toLowerCase();
    return player?.isBot === true || username.includes('bot');
  }

  isGameInProgress(state: GameStateEntity): boolean {
    const status = String(state.status ?? '').toLowerCase();
    const players = state.players ?? [];

    return (
      status === 'finished' ||
      (typeof state.turnIndex === 'number' && state.turnIndex > 0) ||
      players.some((p) => {
        const hasList =
          Array.isArray((p as any).shoppingList) &&
          (p as any).shoppingList.length > 0;
        const hasBasket =
          Array.isArray((p as any).basket) && (p as any).basket.length > 0;
        const hasInventory =
          Array.isArray((p as any).inventory) &&
          (p as any).inventory.length > 0;
        return hasList || hasBasket || hasInventory;
      })
    );
  }

  removeOne<T>(arr: T[], value: T): T[] {
    const copy = Array.isArray(arr) ? [...arr] : [];
    const idx = copy.findIndex((v) => v === value);
    if (idx >= 0) copy.splice(idx, 1);
    return copy;
  }

  formatCourseLabel(courseId: unknown): string {
    const raw = typeof courseId === 'string' ? courseId.trim() : '';
    if (!raw) return '';
    return PanierExpressUtils.COURSE_LABELS[raw] ?? raw;
  }

  formatCourseLabels(list: Iterable<unknown> | null | undefined): string[] {
    if (!list) return [];
    return Array.from(list)
      .map((v) => this.formatCourseLabel(v))
      .filter((s) => s.length > 0);
  }

  formatEventLabel(eventId: unknown): string {
    const raw = typeof eventId === 'string' ? eventId.trim() : '';
    if (!raw) return '';
    const direct = PanierExpressUtils.EVENT_LABELS[raw];
    if (direct) return direct;

    const tokenMap: Record<string, string> = {
      echange: 'échange',
      marche: 'marché',
      intemperie: 'intempérie',
      avarie: 'avarié',
      controle: 'contrôle',
      ephemere: 'éphémère',
      fidelite: 'fidélité',
      abime: 'abîmé',
      detrempe: 'détrempé',
      derriere: 'derrière',
      impose: 'imposé',
      perce: 'percé',
      spontane: 'spontané',
      genereux: 'généreux',
      improvise: 'improvisé',
    };
    const extraTokenMap: Record<string, string> = {
      recompensee: 'r\u00e9compens\u00e9e',
      inversee: 'invers\u00e9e',
      fete: 'f\u00eate',
      ferme: 'ferm\u00e9',
      bonde: 'bond\u00e9',
      defectueux: 'd\u00e9fectueux',
      oublie: 'oubli\u00e9',
      anime: 'animé',
      spontanee: 'spontanée',
    };
    const words = raw
      .split('-')
      .map((token) => tokenMap[token] ?? extraTokenMap[token] ?? token)
      .filter((t) => t.length > 0);
    if (!words.length) return raw;
    const label = words.join(' ');
    return label.charAt(0).toUpperCase() + label.slice(1);
  }

  getTileLabel(tile: any): string {
    if (!tile) return 'inconnu';

    switch (tile.type) {
      case 'start':
        return 'départ';
      case 'rest':
        return 'repos';
      case 'stand':
        return `stand ${tile.standId ?? 'inconnu'}`;
      case 'event':
        return 'événement';
      case 'exchange':
        return 'échange';
      case 'quiz':
        return 'quiz';
      case 'move':
        return 'avancer ou reculer';
      case 'move_to_stand':
        return "avance jusqu'au prochain stand";
      case 'skip':
        return 'perd un tour';
      case 'bonus_course':
        return 'pioche course bonus';
      default:
        return tile?.id ?? 'inconnu';
    }
  }
}

import { Injectable } from '@nestjs/common';
import type { GameStateEntity } from '../../../../core/entities/game-state.entity';
import { GameCoreService } from '../../../../core/services/game-core.service';
import { VictoryService } from '../../../../modules/victory/services/victory.service';
import { TurnFlowService } from '../../../../modules/turn/services/turn-flow.service';
import { ActionLogService } from '../../../../modules/actionlog/services/action-log.service';
import { playingLog } from '../../../../../common/utils/playing-logger';
import { PANIER_EXPRESS_PHASES } from '../definitions/rules.definition';
import { PANIER_EXPRESS_VICTORY } from '../definitions/victory.definition';
import type { PanierExpressMetadata } from '../model/panier-express-state.entity';
import { PanierExpressUtils } from '../model/panier-express-utils.service';

@Injectable()
export class PanierExpressPhaseService {
  private readonly phaseOrder = PANIER_EXPRESS_PHASES;

  constructor(
    private readonly core: GameCoreService,
    private readonly turns: TurnFlowService,
    private readonly victory: VictoryService,
    private readonly actionLogSvc: ActionLogService,
    private readonly utils: PanierExpressUtils,
  ) {}

  advancePhases(state: GameStateEntity): GameStateEntity {
    let next = state;
    for (const phase of this.phaseOrder) {
      if (phase.id === 'check_victory') {
        next = this.applyVictory(next);
      } else if (phase.onEnter) {
        next = phase.onEnter(next);
      }
      if ((next.status || '').toLowerCase() === 'finished') break;
    }
    return next;
  }

  advanceTurn(state: GameStateEntity): GameStateEntity {
    const currentId = state.turn?.currentPlayerId ?? null;
    const currentIndex =
      currentId != null
        ? (state.players ?? []).findIndex((p) => p.id === currentId)
        : state.turnIndex;
    const next = this.turns.advanceTurn(state);

    const meta = this.getMetadata(next);
    const statuses: any = meta.statuses ?? {};
    const turnFlow: any =
      meta && typeof meta === 'object' ? (meta as any).turnFlow : null;

    const decrementMap = (input: Record<number, number> | undefined) => {
      const out: Record<number, number> = {};
      Object.entries(input ?? {}).forEach(([pid, val]) => {
        const nextVal = Math.max(0, Number(val) - 1);
        if (nextVal > 0) out[Number(pid)] = nextVal;
      });
      return out;
    };

    const revealInventory = decrementMap(statuses.revealInventory);
    const revealShoppingList = decrementMap(statuses.revealShoppingList);
    const noDrawCourses = decrementMap(statuses.noDrawCourses);

    let movementDirection: 1 | -1 = meta.movementDirection === -1 ? -1 : 1;
    let movementDirectionOwnerId =
      typeof meta.movementDirectionOwnerId === 'number'
        ? meta.movementDirectionOwnerId
        : null;
    if (
      movementDirection === -1 &&
      movementDirectionOwnerId != null &&
      (next.turn?.currentPlayerId ?? null) === movementDirectionOwnerId
    ) {
      movementDirection = 1;
      movementDirectionOwnerId = null;
    }

    const withMeta: GameStateEntity = {
      ...next,
      metadata: {
        ...(next.metadata as any),
        movementDirection,
        movementDirectionOwnerId,
        statuses: {
          ...statuses,
          revealInventory,
          revealShoppingList,
          noDrawCourses,
        },
      },
      turn: {
        ...(next.turn ?? { currentPlayerId: null, direction: 1 }),
        direction: movementDirection,
      },
    };
    playingLog('panier.advanceTurn', {
      roomId: (state.metadata as any)?.roomId ?? null,
      gameType: (state.metadata as any)?.gameType ?? null,
      userId: currentId,
      type: 'advance_turn',
      currentId,
      currentIndex,
      nextTurnIndex: withMeta.turnIndex,
      nextCurrentPlayerId: withMeta.turn?.currentPlayerId ?? null,
      skipTurn: (withMeta.metadata as any)?.statuses?.skipTurn ?? {},
    });
    const skipped = Array.isArray(turnFlow?.skipped) ? turnFlow.skipped : [];
    if (!skipped.length) {
      return withMeta;
    }

    let out = withMeta;
    for (const entry of skipped) {
      const id = typeof entry?.id === 'number' ? entry.id : null;
      if (id == null) continue;
      const remaining =
        typeof entry?.remainingAfter === 'number' ? entry.remainingAfter : 0;
      const suffix = remaining > 0 ? ` (${remaining} restant)` : '';
      out = this.core.appendLog(
        out,
        `[Panier Express] ${this.utils.playerName(out, id)} passe son tour${suffix}.`,
      );
    }

    const cleanedTurnFlow = {
      ...(turnFlow && typeof turnFlow === 'object' ? turnFlow : {}),
      skipped: [],
    };
    return {
      ...out,
      metadata: {
        ...(out.metadata as any),
        turnFlow: cleanedTurnFlow,
      },
    };
  }

  private applyVictory(state: GameStateEntity): GameStateEntity {
    if ((state.status || '').toLowerCase() === 'finished') return state;
    const meta = this.getMetadata(state);
    const result = this.victory.evaluate(state, PANIER_EXPRESS_VICTORY);
    if (!result || !result.finished) return state;
    const winnerId =
      typeof result.winnerId === 'number' ? result.winnerId : meta.winnerId;
    const nextMeta: PanierExpressMetadata = {
      ...meta,
      winnerId: winnerId ?? null,
    };
    const nextState: GameStateEntity = {
      ...state,
      metadata: nextMeta,
      status: 'finished',
    };
    const winnerName =
      winnerId != null
        ? this.utils.playerName(state, winnerId)
        : 'Partie terminée';
    const logged = this.core.appendLog(
      nextState,
      `[Panier Express] ${winnerName} remporte la partie !`,
    );
    return this.appendActionLog(logged, winnerId ?? null, 'victory', {
      conditionId: result.conditionId,
    });
  }

  private appendActionLog(
    state: GameStateEntity,
    actorId: number | null,
    type: string,
    payload?: Record<string, unknown>,
  ): GameStateEntity {
    const meta = this.getMetadata(state);
    const actionLog = this.actionLogSvc.append(meta.actionLog, {
      actorId,
      type,
      payload,
    });
    return { ...state, metadata: { ...meta, actionLog } };
  }

  private getMetadata(state: GameStateEntity): PanierExpressMetadata {
    return state.metadata as PanierExpressMetadata;
  }
}

﻿import { Injectable } from '@nestjs/common';
import { DeckManagerService } from '../../../../modules/cards/services/deck-manager.service';
import {
  DeckPoolService,
  DeckPoolState,
} from '../../../../modules/cards/services/deck-pool.service';
import { GameStateEntity } from '../../../../core/entities/game-state.entity';
import { seededShuffle } from '../../../../../common/utils/seeded-shuffle';
import {
  PanierExpressDeckPool,
  PanierExpressMetadata,
  PanierExpressTile,
} from '../model/panier-express-state.entity';
import {
  PanierExpressBoardJsonV1,
  PanierExpressCoursesJsonV1,
  PanierExpressEventsJsonV1,
  PanierExpressExchangesJsonV1,
  PanierExpressPawn,
  PanierExpressPawnsJsonV1,
  PanierExpressQuizzesJsonV1,
  PanierExpressStandsJsonV1,
} from '../model/panier-express-content.entity';
import { GameContentLoaderService } from '../../../../engine/services/game-content-loader.service';
import { loadV1Content } from '../../../../setup/content-loader.helper';
import { loadCanonicalPawns } from '../../../../core/helpers/pawn-catalog.helper';

@Injectable()
export class PanierExpressSetupService {
  private static readonly MAX_STAND_ITEMS = 3;

  constructor(
    private readonly decks: DeckManagerService,
    private readonly deckPool: DeckPoolService,
    private readonly contentLoader: GameContentLoaderService,
  ) {}

  private loadBoard(): PanierExpressBoardJsonV1 {
    return loadV1Content<PanierExpressBoardJsonV1>(this.contentLoader, {
      gameType: 'panier-express',
      baseDir: __dirname,
      filename: 'board.json',
      arrayField: 'tiles',
      minItems: 1,
    });
  }

  private loadCourses(): PanierExpressCoursesJsonV1 {
    return loadV1Content<PanierExpressCoursesJsonV1>(this.contentLoader, {
      gameType: 'panier-express',
      baseDir: __dirname,
      filename: 'courses.json',
      arrayField: 'items',
      minItems: 1,
    });
  }

  private loadStands(): PanierExpressStandsJsonV1 {
    return loadV1Content<PanierExpressStandsJsonV1>(this.contentLoader, {
      gameType: 'panier-express',
      baseDir: __dirname,
      filename: 'stands.json',
      arrayField: 'stands',
      minItems: 1,
    });
  }

  private loadEvents(): PanierExpressEventsJsonV1 {
    return loadV1Content<PanierExpressEventsJsonV1>(this.contentLoader, {
      gameType: 'panier-express',
      baseDir: __dirname,
      filename: 'events.json',
      arrayField: 'events',
      minItems: 1,
    });
  }

  private loadExchanges(): PanierExpressExchangesJsonV1 {
    return loadV1Content<PanierExpressExchangesJsonV1>(this.contentLoader, {
      gameType: 'panier-express',
      baseDir: __dirname,
      filename: 'exchanges.json',
      arrayField: 'exchanges',
      minItems: 1,
    });
  }

  private loadQuizzes(): PanierExpressQuizzesJsonV1 {
    return loadV1Content<PanierExpressQuizzesJsonV1>(this.contentLoader, {
      gameType: 'panier-express',
      baseDir: __dirname,
      filename: 'quizzes.json',
      arrayField: 'quizzes',
    });
  }

  private loadPawns(): PanierExpressPawnsJsonV1 {
    return loadV1Content<PanierExpressPawnsJsonV1>(this.contentLoader, {
      gameType: 'panier-express',
      baseDir: __dirname,
      filename: 'pawns.json',
      arrayField: 'pawns',
      minItems: 1,
    });
  }

  courseItems(): string[] {
    return this.loadCourses()
      .items.map((v) => String(v))
      .map((v) => v.trim())
      .filter((v) => v.length > 0);
  }

  eventCards(): string[] {
    return this.loadEvents()
      .events.map((v) => String(v))
      .map((v) => v.trim())
      .filter((v) => v.length > 0);
  }

  exchangeCards(): string[] {
    return this.loadExchanges()
      .exchanges.map((v) => String(v))
      .map((v) => v.trim())
      .filter((v) => v.length > 0);
  }

  standCourseMap(): Record<string, string[]> {
    const out: Record<string, string[]> = {};
    this.loadStands().stands.forEach((s) => {
      if (!s || typeof s.id !== 'string') return;
      const id = s.id.trim();
      if (!id) return;
      const items = Array.isArray(s.items)
        ? s.items
            .map((v) => String(v))
            .map((v) => v.trim())
            .filter((v) => v.length > 0)
            .slice(0, PanierExpressSetupService.MAX_STAND_ITEMS)
        : [];
      out[id] = items;
    });
    return out;
  }

  buildTiles(): PanierExpressTile[] {
    return this.loadBoard().tiles;
  }

  private extractSeed(baseState?: GameStateEntity): number | null {
    const seed = (baseState?.metadata as any)?.rng?.seed;
    return typeof seed === 'number' && Number.isFinite(seed) ? seed : null;
  }

  buildDeckPool(baseState?: GameStateEntity): PanierExpressMetadata['decks'] {
    const seed = this.extractSeed(baseState);
    const shuffle = <T>(items: readonly T[], salt: string): T[] => {
      if (seed != null) return seededShuffle(items, seed, salt);
      return this.deckPool.shuffle([...items]);
    };

    let pool: PanierExpressDeckPool = {};
    pool = this.setDeck(
      pool,
      'courses',
      shuffle(this.courseItems(), 'panier-express:courses'),
    );
    pool = this.setDeck(
      pool,
      'events',
      shuffle(
        this.loadEvents()
          .events.map((v) => String(v))
          .filter((v) => v.length > 0),
        'panier-express:events',
      ),
    );
    pool = this.setDeck(
      pool,
      'exchanges',
      shuffle(
        this.loadExchanges()
          .exchanges.map((v) => String(v))
          .filter((v) => v.length > 0),
        'panier-express:exchanges',
      ),
    );
    pool = this.setDeck(pool, 'quizzes', this.buildQuizDeck(seed));
    const standMap = this.standCourseMap();
    const standIds = new Set<string>();
    this.buildTiles()
      .filter((t) => t.type === 'stand')
      .forEach((t: any) => standIds.add(t.standId));
    standIds.add('bonus');
    standIds.forEach((standId) => {
      const items = standMap[standId] ?? this.courseItems();
      const deck = this.buildReplenishableDeck(items);
      pool = this.setDeck(
        pool,
        `courses-${standId}`,
        shuffle(deck, `panier-express:courses-${standId}`),
      );
    });

    return pool;
  }

  buildQuizDeck(seed?: number | null): Array<{
    id?: string;
    question: string;
    answer: string;
    choices: string[];
  }> {
    const quizzes = this.loadQuizzes().quizzes ?? [];
    const normalized = quizzes
      .map((q) => ({
        id:
          typeof (q as any)?.id === 'string'
            ? String((q as any).id)
            : undefined,
        question: String((q as any)?.question ?? '').trim(),
        answer: String((q as any)?.answer ?? '').trim(),
        choices: Array.isArray((q as any)?.choices)
          ? (q as any).choices
              .map((v: any) => String(v))
              .map((v: string) => v.trim())
              .filter((v: string) => v.length > 0)
          : [],
      }))
      .filter((q) => q.question.length > 0 && q.answer.length > 0);
    if (seed != null) {
      return seededShuffle(normalized, seed, 'panier-express:quizzes');
    }
    return this.decks.shuffle(normalized);
  }

  pawns(): string[] {
    return this.pawnChoices().map((p) => p.name);
  }

  pawnChoices(): PanierExpressPawn[] {
    return loadCanonicalPawns(this.loadPawns().pawns)
      .map((pawn) => ({
        id: pawn.id,
        name: pawn.name,
        description: pawn.description,
      }))
      .filter((p) => p.id.length > 0 && p.name.length > 0);
  }

  /**
   * Les stands doivent pouvoir être revisités plusieurs fois au cours d'une même partie.
   * On duplique volontairement les cartes disponibles pour simuler le réassort permanent.
   */
  buildReplenishableDeck(items?: string[]): string[] {
    const source = items && items.length ? [...items] : [...this.courseItems()];
    return [...source, ...source];
  }

  private setDeck<T>(
    pool: PanierExpressDeckPool,
    key: string,
    deck: T[],
  ): PanierExpressDeckPool {
    const updated = this.deckPool.set<T>(pool as DeckPoolState<T>, key, deck);
    return updated as PanierExpressDeckPool;
  }
}

﻿import { Injectable } from '@nestjs/common';
import type {
  GameStateEntity,
  PendingState,
} from '../../../../core/entities/game-state.entity';
import {
  applyActionsSequentially,
  dispatchByActionType,
  normalizeActionType,
} from '../../../../actions/action-service.helper';
import { resolvePlayerNameFromState } from '../../../../modules/turn-policies/player-name.helper';

import type { GameSingleActionDto } from '../../../../engine/dto/game-action.dto';

import { GameCoreService } from '../../../../core/services/game-core.service';
import { RandomService } from '../../../../modules/random/services/random.service';
import { DeckPoliciesService } from '../../../../modules/deck-policies/services/deck-policies.service';
import { SacAMalicesSetupService } from '../setup/sac-a-malices-setup.service';
import type {
  SacCard,
  SacDeck,
  SacMetadata,
  SacTile,
} from '../model/sac-a-malices.types';
import {
  SAC_VARIANT_BY_ID,
  parseVariantInput,
} from '../sac-a-malices-variants';

@Injectable()
export class SacAMalicesActionService {
  constructor(
    private readonly random: RandomService,
    private readonly core: GameCoreService,
    private readonly setup: SacAMalicesSetupService,
    private readonly deckPolicies: DeckPoliciesService,
  ) {}

  applyActions(
    state: GameStateEntity,
    actions: GameSingleActionDto[],
  ): GameStateEntity {
    const next = applyActionsSequentially(state, actions, (next, action) => {
      const type = normalizeActionType(action);
      return dispatchByActionType(
        type,
        {
          sac_set_variant: () => {
            next = this.applyVariantConfig(next, action);
            return next;
          },
          roll: () => {
            next = this.handleRoll(next);
            return next;
          },
          buy: () => {
            next = this.handleBuy(next, true);
            return next;
          },
          skip_buy: () => {
            next = this.handleBuy(next, false);
            return next;
          },
          build: () => {
            next = this.openChooseProperty(next, 'build');
            return next;
          },
          sell_building: () => {
            next = this.openChooseProperty(next, 'sell_building');
            return next;
          },
          mortgage: () => {
            next = this.openChooseProperty(next, 'mortgage');
            return next;
          },
          unmortgage: () => {
            next = this.openChooseProperty(next, 'unmortgage');
            return next;
          },
          choose_property: () => {
            next = this.handleChooseProperty(next, action);
            return next;
          },
          pay_fine: () => {
            next = this.handlePayFine(next);
            return next;
          },
          use_jail_card: () => {
            next = this.handleUseJailCard(next);
            return next;
          },
        },
        () => next,
      );
    });
    return next;
  }

  private applyVariantConfig(
    state: GameStateEntity,
    action: GameSingleActionDto,
  ): GameStateEntity {
    const meta = this.getMeta(state);
    if (meta.setupStep !== 'setup_config') return state;

    const payload = (action?.payload ?? {}) as any;
    const rawVariant =
      payload.variant ?? payload.variantId ?? payload.value ?? null;
    const parsed =
      parseVariantInput(rawVariant) ??
      parseVariantInput(meta.variantId) ??
      'classic';
    const variant = SAC_VARIANT_BY_ID[parsed] ?? SAC_VARIANT_BY_ID['classic'];
    const chosenId = variant?.id ?? 'classic';

    let next = this.setup.applyVariantSelection(state, chosenId);
    const actorId =
      typeof (action as any)?.meta?.actorId === 'number'
        ? (action as any).meta.actorId
        : null;
    const label = variant?.label ?? chosenId;
    if (rawVariant == null || parseVariantInput(rawVariant) == null) {
      next = this.core.appendLog(next, `Variante inconnue, défaut "${label}".`);
    } else if (actorId != null) {
      next = this.core.appendLog(
        next,
        `${resolvePlayerNameFromState(next, actorId)} choisit la variante : ${label}.`,
      );
    } else {
      next = this.core.appendLog(next, `Variante choisie : ${label}.`);
    }
    return next;
  }

  private handleRoll(state: GameStateEntity): GameStateEntity {
    if (String(state.status ?? '').toLowerCase() !== 'started') return state;
    if (state.pending) return state;
    const currentId = state.turn?.currentPlayerId ?? null;
    if (currentId == null) return state;

    let meta = this.getMeta(state);
    if (meta.statuses?.eliminated?.[currentId]) {
      return this.advanceTurn(state);
    }

    const rules = this.getRules(meta);

    // Prison
    const jailTurns = meta.statuses?.inJail?.[currentId] ?? 0;
    if (jailTurns > 0) {
      if (rules.jail.allowDoubleEscape) {
        // 2d6 : si double => sortie immédiate et déplacement ; sinon on attend.
        const r1 = this.random.rollDice(meta as any, 6);
        const r2 = this.random.rollDice(r1.meta, 6);
        meta = { ...meta, ...r2.meta };
        const d1 = r1.roll;
        const d2 = r2.roll;
        const sum = d1 + d2;
        const isDouble = d1 === d2;

        let next: GameStateEntity = {
          ...state,
          lastRoll: sum,
          metadata: { ...(state.metadata ?? {}), ...meta },
        };
        next = this.core.appendLog(
          next,
          `${resolvePlayerNameFromState(next, currentId)} lance les dés : "${d1}" + "${d2}" = "${sum}".`,
        );

        if (!isDouble) {
          const remainingTurns = Math.max(0, jailTurns - 1);
          next = this.setJailTurns(next, currentId, remainingTurns);
          if (remainingTurns <= 0) {
            if (rules.jail.autoFine > 0) {
              next = this.core.appendLog(
                next,
                `Sortie automatique : amende ${rules.jail.autoFine} €.`,
              );
              next = this.addMoney(next, currentId, -rules.jail.autoFine, {
                toPot: true,
              });
            } else {
              next = this.core.appendLog(next, 'Sortie automatique.');
            }
            next = this.setJailTurns(next, currentId, 0);
          } else {
            next = this.core.appendLog(
              next,
              `Prison : il reste ${remainingTurns} tour(s).`,
            );
          }
          next = this.checkWinner(next);
          if (this.getMeta(next).winnerId != null)
            return { ...next, status: 'finished' };
          return this.advanceTurn(next);
        }

        next = this.core.appendLog(next, 'Double : vous sortez de prison.');
        next = this.setJailTurns(next, currentId, 0);
        next = this.setConsecutiveDoubles(next, currentId, 0);

        // On rejoue / on se déplace normalement après la sortie.
        next = this.moveForward(next, currentId, sum);
        next = this.applyLanding(next, currentId);
        next = this.checkWinner(next);
        if (this.getMeta(next).winnerId != null)
          return { ...next, status: 'finished' };
        if (next.pending) {
          next = this.setExtraRoll(next, currentId, true);
          return next;
        }
        next = this.core.appendLog(next, 'Double : vous rejouez.');
        next = this.setExtraRoll(next, currentId, true);
        return next;
      }

      // Version "attente" : on attend N tours, puis amende auto (si configurée).
      let next = this.setJailTurns(
        state,
        currentId,
        Math.max(0, jailTurns - 1),
      );
      const remaining = this.getMeta(next).statuses?.inJail?.[currentId] ?? 0;
      if (remaining <= 0) {
        if (rules.jail.autoFine > 0) {
          next = this.core.appendLog(
            next,
            `Sortie automatique : amende ${rules.jail.autoFine} €.`,
          );
          next = this.addMoney(next, currentId, -rules.jail.autoFine, {
            toPot: true,
          });
        } else {
          next = this.core.appendLog(next, 'Sortie automatique.');
        }
      } else {
        next = this.core.appendLog(
          next,
          `Prison : il reste ${remaining} tour(s).`,
        );
      }
      next = this.checkWinner(next);
      if (this.getMeta(next).winnerId != null)
        return { ...next, status: 'finished' };
      return this.advanceTurn(next);
    }

    // On consomme l'éventuel bonus "rejouer" à l'entrée du lancer.
    state = this.setExtraRoll(state, currentId, false);
    meta = this.getMeta(state);

    // 2d6
    const r1 = this.random.rollDice(meta as any, 6);
    const r2 = this.random.rollDice(r1.meta, 6);
    meta = { ...meta, ...r2.meta };
    const d1 = r1.roll;
    const d2 = r2.roll;
    const sum = d1 + d2;
    const isDouble = d1 === d2;

    let next: GameStateEntity = {
      ...state,
      lastRoll: sum,
      metadata: { ...(state.metadata ?? {}), ...meta },
    };

    next = this.core.appendLog(
      next,
      `${resolvePlayerNameFromState(next, currentId)} lance les dés : "${d1}" + "${d2}" = "${sum}".`,
    );

    // Doubles : rejouer, 3 doubles consécutifs => prison.
    const prevDoubles =
      this.getMeta(next).statuses?.consecutiveDoubles?.[currentId] ?? 0;
    const doubles = isDouble ? prevDoubles + 1 : 0;
    next = this.setConsecutiveDoubles(next, currentId, doubles);
    if (doubles >= 3) {
      next = this.core.appendLog(next, 'Trois doubles : direction la prison.');
      next = this.sendToJail(next, currentId);
      next = this.setConsecutiveDoubles(next, currentId, 0);
      next = this.setExtraRoll(next, currentId, false);
      next = this.checkWinner(next);
      if (this.getMeta(next).winnerId != null)
        return { ...next, status: 'finished' };
      return this.advanceTurn(next);
    }

    meta = this.getMeta(next);
    if (meta.statuses?.eliminated?.[currentId]) {
      next = this.checkWinner(next);
      if (this.getMeta(next).winnerId != null)
        return { ...next, status: 'finished' };
      return this.advanceTurn(next);
    }

    // (prison gérée avant le lancer)

    // Déplacement
    next = this.moveForward(next, currentId, sum);
    next = this.applyLanding(next, currentId);
    next = this.checkWinner(next);
    if (this.getMeta(next).winnerId != null)
      return { ...next, status: 'finished' };
    if (next.pending) {
      if (isDouble) {
        next = this.setExtraRoll(next, currentId, true);
      }
      return next;
    }

    if (isDouble) {
      next = this.core.appendLog(next, 'Double : vous rejouez.');
      next = this.setExtraRoll(next, currentId, true);
      return next;
    }

    return this.advanceTurn(next);
  }

  private handleBuy(state: GameStateEntity, accept: boolean): GameStateEntity {
    if (String(state.status ?? '').toLowerCase() !== 'started') return state;
    const pending = state.pending as any;
    if (!pending || pending.type !== 'buy') return state;
    const playerId =
      typeof pending.playerId === 'number'
        ? pending.playerId
        : (state.turn?.currentPlayerId ?? null);
    if (playerId == null) return state;

    const tileIndex = Number(pending?.data?.tileIndex);
    if (!Number.isFinite(tileIndex)) return state;

    let next: GameStateEntity = { ...state, pending: null };
    if (!accept) {
      next = this.core.appendLog(
        next,
        `${resolvePlayerNameFromState(next, playerId)} n'achète pas.`,
      );
      next = this.checkWinner(next);
      if (this.getMeta(next).winnerId != null)
        return { ...next, status: 'finished' };
      return this.advanceTurnOrExtraRoll(next, playerId);
    }

    const meta = this.getMeta(next);
    const tile = meta.tiles?.[tileIndex];
    if (!tile) return this.advanceTurnOrExtraRoll(next, playerId);

    if (meta.ownership?.[tileIndex] != null) {
      next = this.core.appendLog(next, 'Déjà acheté.');
      return this.advanceTurnOrExtraRoll(next, playerId);
    }

    const price = this.getPurchasePrice(meta, tile);
    if (price <= 0) {
      next = this.core.appendLog(next, 'Achat impossible (prix inconnu).');
      return this.advanceTurnOrExtraRoll(next, playerId);
    }
    const cash = meta.money?.[playerId] ?? 0;
    if (cash < price) {
      next = this.core.appendLog(next, 'Fonds insuffisants.');
      return this.advanceTurnOrExtraRoll(next, playerId);
    }

    next = this.addMoney(next, playerId, -price, { toPot: false });
    next = this.setOwner(next, tileIndex, playerId);
    next = this.core.appendLog(
      next,
      `${resolvePlayerNameFromState(next, playerId)} achète "${tile.title}" pour ${price} €.`,
    );

    next = this.checkWinner(next);
    if (this.getMeta(next).winnerId != null)
      return { ...next, status: 'finished' };
    return this.advanceTurnOrExtraRoll(next, playerId);
  }

  private handlePayFine(state: GameStateEntity): GameStateEntity {
    if (String(state.status ?? '').toLowerCase() !== 'started') return state;
    if (state.pending) return state;
    const playerId = state.turn?.currentPlayerId ?? null;
    if (playerId == null) return state;

    const meta = this.getMeta(state);
    const rules = this.getRules(meta);
    if (!rules.jail.allowPayFine || rules.jail.autoFine <= 0) {
      return this.core.appendLog(
        state,
        'Sortie de prison par amende : indisponible dans cette variante.',
      );
    }
    const jailTurns = meta.statuses?.inJail?.[playerId] ?? 0;
    if (jailTurns <= 0) return state;

    let next = state;
    next = this.core.appendLog(
      next,
      `Prison : vous payez ${rules.jail.autoFine} € pour sortir.`,
    );
    next = this.addMoney(next, playerId, -rules.jail.autoFine, { toPot: true });
    next = this.setJailTurns(next, playerId, 0);
    next = this.checkWinner(next);
    if (this.getMeta(next).winnerId != null)
      return { ...next, status: 'finished' };
    return next;
  }

  private handleUseJailCard(state: GameStateEntity): GameStateEntity {
    if (String(state.status ?? '').toLowerCase() !== 'started') return state;
    if (state.pending) return state;
    const playerId = state.turn?.currentPlayerId ?? null;
    if (playerId == null) return state;

    const meta = this.getMeta(state);
    const jailTurns = meta.statuses?.inJail?.[playerId] ?? 0;
    if (jailTurns <= 0) return state;

    const count = meta.statuses?.getOutOfJail?.[playerId] ?? 0;
    if (count <= 0) {
      return this.core.appendLog(
        state,
        'Vous n’avez pas de carte "Sortie de prison".',
      );
    }

    let next = state;
    next = this.core.appendLog(next, 'Carte "Sortie de prison" utilisée.');
    next = this.setGetOutOfJail(next, playerId, count - 1);
    next = this.setJailTurns(next, playerId, 0);
    return next;
  }

  private openChooseProperty(
    state: GameStateEntity,
    kind: 'build' | 'sell_building' | 'mortgage' | 'unmortgage',
  ): GameStateEntity {
    if (String(state.status ?? '').toLowerCase() !== 'started') return state;
    if (state.pending) return state;
    const playerId = state.turn?.currentPlayerId ?? null;
    if (playerId == null) return state;

    const meta = this.getMeta(state);
    const tiles = Array.isArray(meta.tiles) ? meta.tiles : [];
    const myCash = meta.money?.[playerId] ?? 0;

    const options: Array<{ tileIndex: number; label: string }> = [];
    for (let tileIndex = 0; tileIndex < tiles.length; tileIndex += 1) {
      const tile = tiles[tileIndex];
      if (!tile) continue;
      if (meta.ownership?.[tileIndex] !== playerId) continue;

      const b = this.getBuilding(meta, tileIndex);

      if (kind === 'build') {
        if (tile.type !== 'property') continue;
        if (b.mortgaged || b.hotel) continue;
        const group = this.getGroup(meta, tile.group ?? '');
        if (!group) continue;
        if (!this.isGroupComplete(meta, playerId, group)) continue;
        const supportsHotel =
          Number(group?.hotelPrice ?? 0) > 0 &&
          Number(group?.rents?.hotel ?? 0) > 0;
        if (!supportsHotel && b.houses >= 4) continue;
        const nextLevel = clamp(b.houses + 1, 1, 4);
        const houseCost =
          Number(
            group?.housePrices?.[String(nextLevel) as any] ??
              group?.housePrice ??
              0,
          ) || 0;
        const cost =
          supportsHotel && b.houses >= 4
            ? Number(group.hotelPrice ?? 0) || 0
            : houseCost;
        if (!Number.isFinite(cost) || cost <= 0 || myCash < cost) continue;
        options.push({ tileIndex, label: `${tile.title} (coût ${cost} €)` });
        continue;
      }

      if (kind === 'sell_building') {
        if (tile.type !== 'property') continue;
        if (!b.hotel && b.houses <= 0) continue;
        const group = this.getGroup(meta, tile.group ?? '');
        const supportsHotel =
          Number(group?.hotelPrice ?? 0) > 0 &&
          Number(group?.rents?.hotel ?? 0) > 0;
        const refund = (() => {
          if (!group) return 0;
          if (supportsHotel && b.hotel)
            return Math.floor((Number(group.hotelPrice ?? 0) || 0) / 2);
          const level = clamp(b.houses, 1, 4);
          const cost =
            Number(
              group?.housePrices?.[String(level) as any] ??
                group?.housePrice ??
                0,
            ) || 0;
          return Math.floor(cost / 2);
        })();
        options.push({ tileIndex, label: `${tile.title} (remb. ${refund} €)` });
        continue;
      }

      if (kind === 'mortgage') {
        if (b.mortgaged) continue;
        if (tile.type === 'property' && (b.hotel || b.houses > 0)) continue;
        const amount = this.getMortgageValue(meta, tile);
        if (!Number.isFinite(amount) || amount <= 0) continue;
        options.push({ tileIndex, label: `${tile.title} (+${amount} €)` });
        continue;
      }

      if (kind === 'unmortgage') {
        if (!b.mortgaged) continue;
        const cost = this.getUnmortgageCost(meta, tile);
        if (!Number.isFinite(cost) || cost <= 0 || myCash < cost) continue;
        options.push({ tileIndex, label: `${tile.title} (-${cost} €)` });
      }
    }

    if (!options.length) {
      return this.core.appendLog(
        state,
        'Aucune propriété disponible pour cette action.',
      );
    }

    const pending: PendingState = {
      type: 'choose_property',
      playerId,
      blocking: true,
      label:
        kind === 'build'
          ? 'Construire où ?'
          : kind === 'sell_building'
            ? 'Vendre une habitation où ?'
            : kind === 'mortgage'
              ? 'Hypothéquer quoi ?'
              : 'Lever l’hypothèque de quoi ?',
      choices: options.map((o) => o.label),
      data: { kind, options: options.map((o) => ({ tileIndex: o.tileIndex })) },
    };

    return { ...state, pending };
  }

  private handleChooseProperty(
    state: GameStateEntity,
    action: GameSingleActionDto,
  ): GameStateEntity {
    if (String(state.status ?? '').toLowerCase() !== 'started') return state;
    const pending = state.pending as any;
    if (!pending || pending.type !== 'choose_property') return state;

    const playerId =
      typeof pending.playerId === 'number'
        ? pending.playerId
        : (state.turn?.currentPlayerId ?? null);
    if (playerId == null) return state;

    const wanted = Number((action?.payload as any)?.tileIndex);
    const options: Array<{ tileIndex: number }> = Array.isArray(
      pending?.data?.options,
    )
      ? pending.data.options
      : [];
    if (
      !Number.isFinite(wanted) ||
      !options.some((o) => o.tileIndex === wanted)
    )
      return state;

    const kind = String(pending?.data?.kind ?? '').trim();
    let next: GameStateEntity = { ...state, pending: null };

    const meta = this.getMeta(next);
    const tile = meta.tiles?.[wanted];
    if (!tile) return next;
    if (meta.ownership?.[wanted] !== playerId) return next;

    if (kind === 'build') {
      next = this.buildOne(next, playerId, wanted);
    } else if (kind === 'sell_building') {
      next = this.sellOne(next, playerId, wanted);
    } else if (kind === 'mortgage') {
      next = this.mortgageTile(next, playerId, wanted);
    } else if (kind === 'unmortgage') {
      next = this.unmortgageTile(next, playerId, wanted);
    }

    next = this.checkWinner(next);
    if (this.getMeta(next).winnerId != null)
      return { ...next, status: 'finished' };
    return next;
  }

  private applyLanding(
    state: GameStateEntity,
    playerId: number,
  ): GameStateEntity {
    let next = state;
    const meta = this.getMeta(next);
    const tiles = Array.isArray(meta.tiles) ? meta.tiles : [];
    const pos = meta.positions?.[playerId] ?? 0;
    const tile: SacTile | undefined = tiles[pos];
    if (!tile) return next;

    next = this.core.appendLog(
      next,
      `${resolvePlayerNameFromState(next, playerId)} place ${this.pawnLabel(next, playerId)} en case ${pos + 1} (${tile.title}).`,
    );
    if (tile.description && String(tile.description).trim()) {
      next = this.core.appendLog(next, String(tile.description).trim());
    }

    if (tile.type === 'go_to_jail') {
      next = this.core.appendLog(next, 'Direction la prison.');
      return this.sendToJail(next, playerId);
    }

    if (tile.type === 'free') {
      const rules = this.getRules(this.getMeta(next));
      if (!rules.potEnabled) {
        return this.core.appendLog(next, 'Parking : rien ne se passe.');
      }
      const pot = this.getMeta(next).pot ?? 0;
      if (pot > 0) {
        next = this.core.appendLog(
          next,
          `Parc Gratuit : vous récupérez ${pot} €.`,
        );
        next = this.setPot(next, 0);
        next = this.addMoney(next, playerId, pot, { toPot: false });
      } else {
        next = this.core.appendLog(next, 'Parc Gratuit : pot vide.');
      }
      return next;
    }

    if (tile.type === 'tax') {
      const amount = extractEuroAmount(
        `${tile.title} ${tile.description ?? ''}`,
      );
      if (amount > 0) {
        next = this.core.appendLog(next, `Taxe : ${amount} €.`);
        next = this.addMoney(next, playerId, -amount, { toPot: true });
      }
      return next;
    }

    if (tile.type === 'chance') {
      next = this.core.appendLog(next, 'Chance : pioche.');
      return this.drawAndApply(next, playerId, 'chance');
    }

    if (tile.type === 'community') {
      next = this.core.appendLog(next, 'Caisse de Communauté : pioche.');
      return this.drawAndApply(next, playerId, 'community');
    }

    if (
      tile.type === 'property' ||
      tile.type === 'station' ||
      tile.type === 'utility'
    ) {
      const owner = meta.ownership?.[pos];
      if (owner == null) {
        const price = this.getPurchasePrice(meta, tile);
        const pending: PendingState = {
          type: 'buy',
          playerId,
          blocking: true,
          label: `Acheter "${tile.title}" (${price > 0 ? price + ' €' : 'prix inconnu'}) ?`,
          choices: ['Acheter', 'Passer'],
          data: { tileIndex: pos },
        };
        return { ...next, pending };
      }
      if (owner === playerId) return next;
      const rules = this.getRules(meta);
      if (
        rules.rentBlockedInJail &&
        (meta.statuses?.inJail?.[owner] ?? 0) > 0
      ) {
        return this.core.appendLog(
          next,
          'Le propriétaire est en prison : pas de loyer.',
        );
      }
      const b = this.getBuilding(meta, pos);
      if (b.mortgaged) {
        return this.core.appendLog(
          next,
          'Propriété hypothéquée : pas de loyer.',
        );
      }
      const rent = this.getRent(meta, tile, pos, owner, state.lastRoll ?? 0);
      if (rent > 0) {
        next = this.core.appendLog(
          next,
          `Loyer : ${rent} € à ${resolvePlayerNameFromState(next, owner)}.`,
        );
        next = this.addMoney(next, playerId, -rent, { toPot: false });
        next = this.addMoney(next, owner, rent, { toPot: false });
      }
      return next;
    }

    return next;
  }

  private drawAndApply(
    state: GameStateEntity,
    playerId: number,
    deckId: 'chance' | 'community',
  ): GameStateEntity {
    let next = state;
    const meta0 = this.getMeta(next);
    const drawn = this.drawCard(meta0, deckId);
    next = { ...next, metadata: { ...(next.metadata ?? {}), ...drawn.meta } };
    if (!drawn.card) return next;
    next = this.core.appendLog(next, `Carte : ${drawn.card.text}`);
    return this.applyCard(next, playerId, deckId, drawn.card);
  }

  private applyCard(
    state: GameStateEntity,
    playerId: number,
    _deckId: 'chance' | 'community',
    card: SacCard,
  ): GameStateEntity {
    let next = state;
    const text = String(card.text ?? '');

    if (isGetOutOfJailCard(text)) {
      const meta = this.getMeta(next);
      const current = meta.statuses?.getOutOfJail?.[playerId] ?? 0;
      next = this.core.appendLog(next, 'Vous gardez cette carte.');
      return this.setGetOutOfJail(next, playerId, current + 1);
    }

    const everyone = extractAllPlayersMoney(text);
    if (everyone) {
      const meta0 = this.getMeta(next);
      const rules = this.getRules(meta0);
      const players = Array.isArray(next.players) ? next.players : [];
      const alive = players
        .map((p) => p?.id)
        .filter(
          (id): id is number => typeof id === 'number' && Number.isFinite(id),
        )
        .filter((id) => !meta0.statuses?.eliminated?.[id]);

      if (everyone.kind === 'pay') {
        next = this.core.appendLog(
          next,
          `Tous les joueurs paient ${everyone.amount} €.`,
        );
        for (const id of alive) {
          next = this.addMoney(next, id, -everyone.amount, {
            toPot: rules.potEnabled && !everyone.toBank,
          });
        }
        return next;
      }
      next = this.core.appendLog(
        next,
        `Tous les joueurs reçoivent ${everyone.amount} €.`,
      );
      for (const id of alive) {
        next = this.addMoney(next, id, everyone.amount, { toPot: false });
      }
      return next;
    }

    if (mentionsInfrastructureLoss(text)) {
      next = this.core.appendLog(next, 'Vous perdez une infrastructure.');
      return this.loseOneInfrastructure(next, playerId);
    }

    const delta = extractMoveDelta(text);
    if (delta !== 0) {
      next = this.core.appendLog(
        next,
        `Déplacement : ${delta > 0 ? '+' : ''}${delta}.`,
      );
      next = this.moveForward(next, playerId, delta);
      return this.applyLanding(next, playerId);
    }

    if (/retournez\s+à\s+la\s+case\s+départ/i.test(text)) {
      next = this.core.appendLog(next, 'Retour à Départ.');
      return this.moveTo(next, playerId, 0, { collectStart: false });
    }

    const targetName = extractTargetPlace(text);
    if (targetName) {
      const target = this.findTileByName(this.getMeta(next).tiles, targetName);
      if (target != null) {
        next = this.core.appendLog(next, `Déplacement : vers "${targetName}".`);
        next = this.moveTo(next, playerId, target, { collectStart: true });
        return this.applyLanding(next, playerId);
      }
    }

    const skip = extractSkipTurns(text);
    if (skip > 0) {
      next = this.core.appendLog(next, `Vous perdez ${skip} tour(s).`);
      next = this.addSkip(next, playerId, skip);
      return next;
    }

    const money = extractMoneyDelta(text);
    if (money !== 0) {
      next = this.core.appendLog(
        next,
        `Caisse : ${money > 0 ? '+' : ''}${money} €.`,
      );
      next = this.addMoney(next, playerId, money, { toPot: money < 0 });
      return next;
    }

    // Autres effets non implémentés : on log seulement.
    return next;
  }

  private drawCard(
    meta: SacMetadata,
    deckId: 'chance' | 'community',
  ): { card: SacCard | null; meta: SacMetadata } {
    const deck: SacDeck = meta.decks?.[deckId] ?? { cards: [], discard: [] };
    const cards = Array.isArray(deck.cards) ? [...deck.cards] : [];
    const discard = Array.isArray(deck.discard) ? [...deck.discard] : [];
    const draw = this.deckPolicies.drawFromPile<SacCard, SacMetadata>({
      meta,
      pile: cards,
      discard,
      useWholeMetaRng: true,
      discardDrawnCard: false,
    });
    if (!draw.card) {
      const nextMeta: SacMetadata = {
        ...draw.meta,
        decks: {
          ...meta.decks,
          [deckId]: { cards: draw.pile as any, discard: draw.discard as any },
        },
      };
      return { card: null, meta: nextMeta };
    }
    const card = draw.card;
    const keep = isGetOutOfJailCard(String(card.text ?? ''));
    const nextDeck = keep
      ? { cards: draw.pile, discard: draw.discard }
      : { cards: draw.pile, discard: [...draw.discard, card] };
    const nextMeta: SacMetadata = {
      ...draw.meta,
      decks: { ...meta.decks, [deckId]: nextDeck },
    };
    return { card, meta: nextMeta };
  }

  private moveForward(
    state: GameStateEntity,
    playerId: number,
    delta: number,
  ): GameStateEntity {
    const meta = this.getMeta(state);
    const rules = this.getRules(meta);
    const tiles = Array.isArray(meta.tiles) ? meta.tiles : [];
    const len = tiles.length || 40;
    const pos = meta.positions?.[playerId] ?? 0;
    const nextPos = (((pos + delta) % len) + len) % len;
    let next = this.setPos(state, playerId, nextPos);
    if (delta > 0 && nextPos < pos) {
      next = this.core.appendLog(
        next,
        `Passage sur Départ : +${rules.passStartBonus} €.`,
      );
      next = this.addMoney(next, playerId, rules.passStartBonus, {
        toPot: false,
      });
    }
    return next;
  }

  private moveTo(
    state: GameStateEntity,
    playerId: number,
    pos: number,
    options: { collectStart: boolean },
  ): GameStateEntity {
    const meta = this.getMeta(state);
    const rules = this.getRules(meta);
    const tiles = Array.isArray(meta.tiles) ? meta.tiles : [];
    const len = tiles.length || 40;
    const current = meta.positions?.[playerId] ?? 0;
    const target = clamp(pos, 0, len - 1);
    let next = this.setPos(state, playerId, target);
    if (options.collectStart && target < current) {
      next = this.core.appendLog(
        next,
        `Passage sur Départ : +${rules.passStartBonus} €.`,
      );
      next = this.addMoney(next, playerId, rules.passStartBonus, {
        toPot: false,
      });
    }
    return next;
  }

  private sendToJail(
    state: GameStateEntity,
    playerId: number,
  ): GameStateEntity {
    const meta = this.getMeta(state);
    const rules = this.getRules(meta);
    const jailPos = this.findJailTile(meta.tiles) ?? 30;
    let next = this.setPos(state, playerId, jailPos);
    next = this.setJailTurns(next, playerId, rules.jail.maxTurns);
    return next;
  }

  private findJailTile(tiles: SacTile[] | undefined): number | null {
    const list = Array.isArray(tiles) ? tiles : [];
    const idx = list.findIndex((t) => t?.type === 'jail');
    return idx >= 0 ? idx : null;
  }

  private findTileByName(
    tiles: SacTile[] | undefined,
    rawName: string,
  ): number | null {
    const name = normalize(rawName);
    if (!name) return null;
    const list = Array.isArray(tiles) ? tiles : [];
    const idx = list.findIndex((t) =>
      normalize(stripParens(t?.title ?? '')).includes(name),
    );
    return idx >= 0 ? idx : null;
  }

  private setPos(
    state: GameStateEntity,
    playerId: number,
    pos: number,
  ): GameStateEntity {
    const meta = this.getMeta(state);
    const tiles = Array.isArray(meta.tiles) ? meta.tiles : [];
    const len = tiles.length || 40;
    const nextPos = clamp(pos, 0, len - 1);
    const nextMeta: SacMetadata = {
      ...meta,
      positions: { ...(meta.positions ?? {}), [playerId]: nextPos },
    };
    return { ...state, metadata: { ...(state.metadata ?? {}), ...nextMeta } };
  }

  private setOwner(
    state: GameStateEntity,
    tileIndex: number,
    ownerId: number,
  ): GameStateEntity {
    const meta = this.getMeta(state);
    const nextMeta: SacMetadata = {
      ...meta,
      ownership: { ...(meta.ownership ?? {}), [tileIndex]: ownerId },
    };
    return { ...state, metadata: { ...(state.metadata ?? {}), ...nextMeta } };
  }

  private setPot(state: GameStateEntity, value: number): GameStateEntity {
    const meta = this.getMeta(state);
    const nextMeta: SacMetadata = {
      ...meta,
      pot: Math.max(0, Math.trunc(value)),
    };
    return { ...state, metadata: { ...(state.metadata ?? {}), ...nextMeta } };
  }

  private addSkip(
    state: GameStateEntity,
    playerId: number,
    turns: number,
  ): GameStateEntity {
    const meta = this.getMeta(state);
    const current = meta.statuses?.skipTurn?.[playerId] ?? 0;
    const nextMeta: SacMetadata = {
      ...meta,
      statuses: {
        ...meta.statuses,
        skipTurn: {
          ...(meta.statuses.skipTurn ?? {}),
          [playerId]: current + turns,
        },
      },
    };
    return { ...state, metadata: { ...(state.metadata ?? {}), ...nextMeta } };
  }

  private setJailTurns(
    state: GameStateEntity,
    playerId: number,
    turns: number,
  ): GameStateEntity {
    const meta = this.getMeta(state);
    const nextMeta: SacMetadata = {
      ...meta,
      statuses: {
        ...meta.statuses,
        inJail: {
          ...(meta.statuses.inJail ?? {}),
          [playerId]: Math.max(0, Math.trunc(turns)),
        },
      },
    };
    return { ...state, metadata: { ...(state.metadata ?? {}), ...nextMeta } };
  }

  private setGetOutOfJail(
    state: GameStateEntity,
    playerId: number,
    count: number,
  ): GameStateEntity {
    const meta = this.getMeta(state);
    const nextMeta: SacMetadata = {
      ...meta,
      statuses: {
        ...meta.statuses,
        getOutOfJail: {
          ...(meta.statuses.getOutOfJail ?? {}),
          [playerId]: Math.max(0, Math.trunc(count)),
        },
      },
    };
    return { ...state, metadata: { ...(state.metadata ?? {}), ...nextMeta } };
  }

  private setExtraRoll(
    state: GameStateEntity,
    playerId: number,
    value: boolean,
  ): GameStateEntity {
    const meta = this.getMeta(state);
    const nextMeta: SacMetadata = {
      ...meta,
      statuses: {
        ...meta.statuses,
        extraRoll: {
          ...(meta.statuses.extraRoll ?? {}),
          [playerId]: Boolean(value),
        },
      },
    };
    return { ...state, metadata: { ...(state.metadata ?? {}), ...nextMeta } };
  }

  private setConsecutiveDoubles(
    state: GameStateEntity,
    playerId: number,
    value: number,
  ): GameStateEntity {
    const meta = this.getMeta(state);
    const nextMeta: SacMetadata = {
      ...meta,
      statuses: {
        ...meta.statuses,
        consecutiveDoubles: {
          ...(meta.statuses.consecutiveDoubles ?? {}),
          [playerId]: Math.max(0, Math.trunc(value)),
        },
      },
    };
    return { ...state, metadata: { ...(state.metadata ?? {}), ...nextMeta } };
  }

  private advanceTurnOrExtraRoll(
    state: GameStateEntity,
    playerId: number,
  ): GameStateEntity {
    const meta = this.getMeta(state);
    if (meta.statuses?.eliminated?.[playerId]) return this.advanceTurn(state);
    if (meta.statuses?.extraRoll?.[playerId]) {
      let next = this.setExtraRoll(state, playerId, false);
      next = this.core.appendLog(next, 'Double : vous rejouez.');
      return next;
    }
    return this.advanceTurn(state);
  }

  private getBuilding(
    meta: SacMetadata,
    tileIndex: number,
  ): { houses: number; hotel: boolean; mortgaged: boolean } {
    const current = meta.buildings?.[tileIndex];
    return {
      houses: clamp(Number(current?.houses ?? 0) || 0, 0, 4),
      hotel: Boolean(current?.hotel),
      mortgaged: Boolean(current?.mortgaged),
    };
  }

  private setBuilding(
    state: GameStateEntity,
    tileIndex: number,
    patch: Partial<{ houses: number; hotel: boolean; mortgaged: boolean }>,
  ): GameStateEntity {
    const meta = this.getMeta(state);
    const current = this.getBuilding(meta, tileIndex);
    const nextBuilding = {
      houses: clamp(Number(patch.houses ?? current.houses) || 0, 0, 4),
      hotel: patch.hotel != null ? Boolean(patch.hotel) : current.hotel,
      mortgaged:
        patch.mortgaged != null ? Boolean(patch.mortgaged) : current.mortgaged,
    };
    const nextMeta: SacMetadata = {
      ...meta,
      buildings: { ...(meta.buildings ?? {}), [tileIndex]: nextBuilding },
    };
    return { ...state, metadata: { ...(state.metadata ?? {}), ...nextMeta } };
  }

  private getGroup(meta: SacMetadata, rawGroup: string) {
    const key = normalize(rawGroup);
    if (!key) return null;
    return meta.data?.groups?.find((g) => normalize(g.color) === key) ?? null;
  }

  private isGroupComplete(
    meta: SacMetadata,
    ownerId: number,
    group: any,
  ): boolean {
    const props: string[] = Array.isArray(group?.properties)
      ? group.properties
      : [];
    if (!props.length) return false;
    const idxs = props
      .map((name) => this.findTileByName(meta.tiles, name))
      .filter((idx) => idx != null);
    if (!idxs.length) return false;
    return idxs.every(
      (idx) =>
        meta.ownership?.[idx] === ownerId &&
        !this.getBuilding(meta, idx).mortgaged,
    );
  }

  private getMortgageValue(meta: SacMetadata, tile: SacTile): number {
    if (tile.type === 'station') return meta.data?.stations?.mortgage ?? 0;
    if (tile.type === 'utility') {
      const u = meta.data?.utilities?.find(
        (x) => normalize(x.name) === normalize(tile.title),
      );
      return u?.mortgage ?? 0;
    }
    if (tile.type === 'property') {
      const group = this.getGroup(meta, tile.group ?? '');
      return group?.mortgage ?? 0;
    }
    return 0;
  }

  private getUnmortgageCost(meta: SacMetadata, tile: SacTile): number {
    if (tile.type === 'station')
      return meta.data?.stations?.unmortgageCost ?? 0;
    if (tile.type === 'utility') {
      const u = meta.data?.utilities?.find(
        (x) => normalize(x.name) === normalize(tile.title),
      );
      return u?.unmortgageCost ?? 0;
    }
    if (tile.type === 'property') {
      const group = this.getGroup(meta, tile.group ?? '');
      return group?.unmortgageCost ?? 0;
    }
    return 0;
  }

  private buildOne(
    state: GameStateEntity,
    playerId: number,
    tileIndex: number,
  ): GameStateEntity {
    const meta = this.getMeta(state);
    const tile = meta.tiles?.[tileIndex];
    if (!tile || tile.type !== 'property') return state;
    const group = this.getGroup(meta, tile.group ?? '');
    if (!group) return state;
    if (!this.isGroupComplete(meta, playerId, group)) return state;

    const b = this.getBuilding(meta, tileIndex);
    if (b.mortgaged || b.hotel) return state;
    const supportsHotel =
      Number(group?.hotelPrice ?? 0) > 0 &&
      Number(group?.rents?.hotel ?? 0) > 0;
    if (!supportsHotel && b.houses >= 4) return state;

    const nextLevel = clamp(b.houses + 1, 1, 4);
    const houseCost =
      Number(
        group?.housePrices?.[String(nextLevel) as any] ??
          group?.housePrice ??
          0,
      ) || 0;
    const cost =
      supportsHotel && b.houses >= 4
        ? Number(group.hotelPrice ?? 0) || 0
        : houseCost;
    const cash = meta.money?.[playerId] ?? 0;
    if (!Number.isFinite(cost) || cost <= 0 || cash < cost) return state;

    let next = state;
    next = this.addMoney(next, playerId, -cost, { toPot: false });
    if (this.getMeta(next).statuses?.eliminated?.[playerId]) return next;

    if (supportsHotel && b.houses >= 4) {
      next = this.core.appendLog(next, `Hôtel construit sur "${tile.title}".`);
      return this.setBuilding(next, tileIndex, { hotel: true, houses: 0 });
    }
    next = this.core.appendLog(next, `Maison construite sur "${tile.title}".`);
    return this.setBuilding(next, tileIndex, {
      houses: b.houses + 1,
      hotel: false,
    });
  }

  private sellOne(
    state: GameStateEntity,
    playerId: number,
    tileIndex: number,
  ): GameStateEntity {
    const meta = this.getMeta(state);
    const tile = meta.tiles?.[tileIndex];
    if (!tile || tile.type !== 'property') return state;
    const group = this.getGroup(meta, tile.group ?? '');
    if (!group) return state;
    const supportsHotel =
      Number(group?.hotelPrice ?? 0) > 0 &&
      Number(group?.rents?.hotel ?? 0) > 0;

    const b = this.getBuilding(meta, tileIndex);
    if (!b.hotel && b.houses <= 0) return state;

    if (supportsHotel && b.hotel) {
      const refund = Math.floor((group.hotelPrice ?? 0) / 2);
      let next = this.core.appendLog(
        state,
        `Hôtel vendu sur "${tile.title}" (+${refund} €).`,
      );
      next = this.setBuilding(next, tileIndex, { hotel: false, houses: 4 });
      return this.addMoney(next, playerId, refund, { toPot: false });
    }

    const level = clamp(b.houses, 1, 4);
    const cost =
      Number(
        group?.housePrices?.[String(level) as any] ?? group?.housePrice ?? 0,
      ) || 0;
    const refund = Math.floor(cost / 2);
    let next = this.core.appendLog(
      state,
      `Maison vendue sur "${tile.title}" (+${refund} €).`,
    );
    next = this.setBuilding(next, tileIndex, {
      houses: Math.max(0, b.houses - 1),
    });
    return this.addMoney(next, playerId, refund, { toPot: false });
  }

  private mortgageTile(
    state: GameStateEntity,
    playerId: number,
    tileIndex: number,
  ): GameStateEntity {
    const meta = this.getMeta(state);
    const tile = meta.tiles?.[tileIndex];
    if (!tile) return state;
    if (meta.ownership?.[tileIndex] !== playerId) return state;

    const b = this.getBuilding(meta, tileIndex);
    if (b.mortgaged) return state;
    if (tile.type === 'property' && (b.hotel || b.houses > 0)) return state;

    const amount = this.getMortgageValue(meta, tile);
    if (!Number.isFinite(amount) || amount <= 0) return state;

    let next = this.core.appendLog(
      state,
      `Hypothèque : "${tile.title}" (+${amount} €).`,
    );
    next = this.setBuilding(next, tileIndex, { mortgaged: true });
    return this.addMoney(next, playerId, amount, { toPot: false });
  }

  private unmortgageTile(
    state: GameStateEntity,
    playerId: number,
    tileIndex: number,
  ): GameStateEntity {
    const meta = this.getMeta(state);
    const tile = meta.tiles?.[tileIndex];
    if (!tile) return state;
    if (meta.ownership?.[tileIndex] !== playerId) return state;

    const b = this.getBuilding(meta, tileIndex);
    if (!b.mortgaged) return state;

    const cost = this.getUnmortgageCost(meta, tile);
    const cash = meta.money?.[playerId] ?? 0;
    if (!Number.isFinite(cost) || cost <= 0 || cash < cost) return state;

    let next = this.core.appendLog(
      state,
      `Levée d’hypothèque : "${tile.title}" (-${cost} €).`,
    );
    next = this.addMoney(next, playerId, -cost, { toPot: false });
    if (this.getMeta(next).statuses?.eliminated?.[playerId]) return next;
    return this.setBuilding(next, tileIndex, { mortgaged: false });
  }

  private loseOneInfrastructure(
    state: GameStateEntity,
    playerId: number,
  ): GameStateEntity {
    const meta0 = this.getMeta(state);
    const tiles = Array.isArray(meta0.tiles) ? meta0.tiles : [];

    const ownedWithInfra: number[] = [];
    for (let i = 0; i < tiles.length; i += 1) {
      const owner = meta0.ownership?.[i];
      if (owner !== playerId) continue;
      const tile = tiles[i];
      if (!tile || tile.type !== 'property') continue;
      const b = this.getBuilding(meta0, i);
      if (b.hotel || b.houses > 0) ownedWithInfra.push(i);
    }

    if (!ownedWithInfra.length) {
      return this.core.appendLog(state, 'Aucune infrastructure à perdre.');
    }

    const picked = this.random.pickOne(meta0 as any, ownedWithInfra);
    let next: GameStateEntity = {
      ...state,
      metadata: {
        ...(state.metadata ?? {}),
        ...meta0,
        ...picked.meta,
      },
    };
    const tileIndex = picked.value;
    if (tileIndex == null) return next;

    const tile = tiles[tileIndex];
    const group = tile
      ? this.getGroup(this.getMeta(next), tile.group ?? '')
      : null;
    const supportsHotel =
      Number(group?.hotelPrice ?? 0) > 0 &&
      Number(group?.rents?.hotel ?? 0) > 0;

    const b = this.getBuilding(this.getMeta(next), tileIndex);
    if (supportsHotel && b.hotel) {
      next = this.core.appendLog(
        next,
        `Infrastructure perdue : hôtel sur "${tile?.title ?? 'propriété'}".`,
      );
      return this.setBuilding(next, tileIndex, { hotel: false, houses: 4 });
    }
    if (b.houses > 0) {
      next = this.core.appendLog(
        next,
        `Infrastructure perdue : -1 sur "${tile?.title ?? 'propriété'}".`,
      );
      return this.setBuilding(next, tileIndex, {
        houses: Math.max(0, b.houses - 1),
      });
    }
    return next;
  }

  private addMoney(
    state: GameStateEntity,
    playerId: number,
    delta: number,
    options: { toPot: boolean },
  ): GameStateEntity {
    const meta = this.getMeta(state);
    const current = meta.money?.[playerId] ?? 0;
    const nextMoney = current + delta;
    const rules = this.getRules(meta);
    const nextMeta: SacMetadata = {
      ...meta,
      money: { ...(meta.money ?? {}), [playerId]: nextMoney },
      pot:
        rules.potEnabled && options.toPot
          ? (meta.pot ?? 0) + Math.max(0, -delta)
          : (meta.pot ?? 0),
    };
    let next: GameStateEntity = {
      ...state,
      metadata: { ...(state.metadata ?? {}), ...nextMeta },
    };
    if (nextMoney < 0) {
      next = this.core.appendLog(
        next,
        `${resolvePlayerNameFromState(next, playerId)} est en faillite !`,
      );
      next = this.setEliminated(next, playerId, true);
      next = this.releaseAssets(next, playerId);
    }
    return next;
  }

  private releaseAssets(
    state: GameStateEntity,
    playerId: number,
  ): GameStateEntity {
    const meta = this.getMeta(state);
    const ownership = { ...(meta.ownership ?? {}) } as any;
    const buildings = { ...(meta.buildings ?? {}) } as any;
    for (const [k, v] of Object.entries(ownership)) {
      if (Number(v) === playerId) {
        delete ownership[k];
        delete buildings[k];
      }
    }

    const money = { ...(meta.money ?? {}), [playerId]: 0 };
    const statuses = meta.statuses ?? ({} as any);
    const nextMeta: SacMetadata = {
      ...meta,
      ownership,
      buildings,
      money,
      statuses: {
        ...statuses,
        inJail: { ...(statuses.inJail ?? {}), [playerId]: 0 },
        skipTurn: { ...(statuses.skipTurn ?? {}), [playerId]: 0 },
        extraRoll: { ...(statuses.extraRoll ?? {}), [playerId]: false },
        consecutiveDoubles: {
          ...(statuses.consecutiveDoubles ?? {}),
          [playerId]: 0,
        },
      },
    };
    return { ...state, metadata: { ...(state.metadata ?? {}), ...nextMeta } };
  }

  private setEliminated(
    state: GameStateEntity,
    playerId: number,
    value: boolean,
  ): GameStateEntity {
    const meta = this.getMeta(state);
    const nextMeta: SacMetadata = {
      ...meta,
      statuses: {
        ...meta.statuses,
        eliminated: {
          ...(meta.statuses.eliminated ?? {}),
          [playerId]: Boolean(value),
        },
      },
    };
    return { ...state, metadata: { ...(state.metadata ?? {}), ...nextMeta } };
  }

  private getPurchasePrice(meta: SacMetadata, tile: SacTile): number {
    if (tile.type === 'station') return meta.data?.stations?.purchasePrice ?? 0;
    if (tile.type === 'utility') {
      const u = meta.data?.utilities?.find(
        (x) => normalize(x.name) === normalize(tile.title),
      );
      return u?.purchasePrice ?? 0;
    }
    if (tile.type === 'property') {
      const group = meta.data?.groups?.find(
        (g) => normalize(g.color) === normalize(tile.group ?? ''),
      );
      return group?.purchasePrice ?? 0;
    }
    return 0;
  }

  private getRent(
    meta: SacMetadata,
    tile: SacTile,
    tileIndex: number,
    ownerId: number,
    lastRoll: number,
  ): number {
    if (tile.type === 'station') {
      const stations = meta.data?.stations?.properties ?? [];
      const count = stations
        .map((name) => this.findTileByName(meta.tiles, name))
        .filter((idx) => idx != null)
        .filter((idx) => meta.ownership?.[idx] === ownerId).length;
      const rents = meta.data?.stations?.rents ?? ({} as any);
      const key = String(clamp(count, 1, 4)) as '1' | '2' | '3' | '4';
      return Number(rents[key] ?? 0) || 0;
    }

    if (tile.type === 'utility') {
      const utils = meta.data?.utilities ?? [];
      const idxs = utils
        .map((u) => this.findTileByName(meta.tiles, u.name))
        .filter((idx) => idx != null);
      const owned = idxs.filter(
        (idx) => meta.ownership?.[idx] === ownerId,
      ).length;
      const multiplier =
        owned >= 2
          ? (utils[0]?.multiplier2 ?? 10)
          : (utils[0]?.multiplier1 ?? 4);
      return Math.max(0, Math.trunc(multiplier * Math.max(0, lastRoll)));
    }

    if (tile.type === 'property') {
      const group = meta.data?.groups?.find(
        (g) => normalize(g.color) === normalize(tile.group ?? ''),
      );
      if (!group) return 0;
      const b = this.getBuilding(meta, tileIndex);
      if (b.hotel) return Number(group.rents?.hotel ?? 0) || 0;
      const houses = clamp(Number(b.houses ?? 0) || 0, 0, 4);
      if (houses <= 0) return Number(group.rents?.base ?? 0) || 0;
      if (houses === 1) return Number(group.rents?.house1 ?? 0) || 0;
      if (houses === 2) return Number(group.rents?.house2 ?? 0) || 0;
      if (houses === 3) return Number(group.rents?.house3 ?? 0) || 0;
      return Number(group.rents?.house4 ?? 0) || 0;
    }

    return 0;
  }

  private advanceTurn(state: GameStateEntity): GameStateEntity {
    const players = Array.isArray(state.players) ? state.players : [];
    if (!players.length) return state;
    const meta = this.getMeta(state);
    const statuses = meta.statuses ?? ({} as any);
    const skipTurn = { ...(statuses.skipTurn ?? {}) };
    const eliminated = statuses.eliminated ?? {};

    const currentId = state.turn?.currentPlayerId ?? null;
    const currentIndex =
      currentId != null
        ? players.findIndex((p: any) => p?.id === currentId)
        : state.turnIndex;

    let nextIndex = currentIndex >= 0 ? currentIndex : state.turnIndex;
    let attempts = 0;
    let nextPlayerId = players[nextIndex]?.id ?? players[0].id;

    do {
      nextIndex = (nextIndex + 1) % players.length;
      const pid = players[nextIndex].id;
      if (eliminated?.[pid]) {
        attempts += 1;
        continue;
      }
      const remaining = skipTurn[pid] ?? 0;
      if (remaining > 0) {
        skipTurn[pid] = remaining - 1;
        attempts += 1;
        continue;
      }
      nextPlayerId = pid;
      break;
    } while (attempts < players.length);

    return {
      ...state,
      turnIndex: nextIndex,
      turn: { currentPlayerId: nextPlayerId, direction: 1 },
      metadata: {
        ...(state.metadata ?? {}),
        ...meta,
        statuses: { ...statuses, skipTurn },
      },
    };
  }

  private checkWinner(state: GameStateEntity): GameStateEntity {
    const meta = this.getMeta(state);
    if (meta.winnerId != null) return state;
    const players = Array.isArray(state.players) ? state.players : [];
    const alive = players
      .map((p) => p?.id)
      .filter(
        (id): id is number => typeof id === 'number' && Number.isFinite(id),
      )
      .filter((id) => !meta.statuses?.eliminated?.[id]);
    if (alive.length === 1) {
      const winnerId = alive[0];
      const nextMeta: SacMetadata = { ...meta, winnerId };
      const next = {
        ...state,
        metadata: { ...(state.metadata ?? {}), ...nextMeta },
      };
      return this.core.appendLog(
        next,
        `${resolvePlayerNameFromState(next, winnerId)} remporte la partie !`,
      );
    }
    return state;
  }

  private getMeta(state: GameStateEntity): SacMetadata {
    return (state.metadata ?? {}) as any as SacMetadata;
  }

  private getRules(meta: SacMetadata): NonNullable<SacMetadata['rules']> {
    const defaults: NonNullable<SacMetadata['rules']> = {
      startMoney: 2000,
      passStartBonus: 200,
      potEnabled: true,
      rentBlockedInJail: true,
      jail: {
        maxTurns: 3,
        autoFine: 100,
        allowPayFine: true,
        allowDoubleEscape: false,
      },
    };
    const r = meta.rules ?? ({} as any);
    return {
      ...defaults,
      ...r,
      jail: { ...defaults.jail, ...(r.jail ?? {}) },
    };
  }

  private pawnLabel(state: GameStateEntity, id: number): string {
    const players = Array.isArray(state.players) ? state.players : [];
    const player: any = players.find((p) => p?.id === id);

    const explicitLabel = String(player?.pawnLabel ?? '').trim();
    if (explicitLabel) return `"${explicitLabel}"`;

    const pawnId = String(player?.pawn ?? '').trim();
    if (pawnId) return `"${pawnId}"`;

    const fallback = resolvePlayerNameFromState(state, id);
    return `"${fallback}"`;
  }
}

function clamp(value: number, min: number, max: number): number {
  if (value < min) return min;
  if (value > max) return max;
  return value;
}

function stripParens(text: string): string {
  return String(text ?? '')
    .replace(/\([^)]*\)/g, '')
    .trim();
}

function normalize(value: string): string {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/[’'`]/g, "'")
    .replace(/\s+/g, ' ');
}

function extractEuroAmount(text: string): number {
  const m = text.match(/(\d+)\s*(€|eur)/i);
  const n = m ? Number(m[1]) : 0;
  return Number.isFinite(n) ? Math.trunc(n) : 0;
}

function extractMoneyDelta(text: string): number {
  const gain = text.match(/(?:recevez|reçois|recois|gagnez|gagne)\s+(\d+)/i);
  if (gain) {
    const n = Number(gain[1]);
    if (Number.isFinite(n)) return Math.trunc(n);
  }
  const pay = text.match(/(?:payez|paie|paye)\s+(\d+)/i);
  if (pay) {
    const n = Number(pay[1]);
    if (Number.isFinite(n)) return -Math.trunc(n);
  }
  return 0;
}

function extractMoveDelta(text: string): number {
  const parse = (raw: string) => {
    const v = raw.trim().toLowerCase();
    const n = Number(v);
    if (Number.isFinite(n)) return n;
    const map: Record<string, number> = {
      un: 1,
      une: 1,
      deux: 2,
      trois: 3,
      quatre: 4,
      cinq: 5,
      six: 6,
    };
    return map[v] ?? 0;
  };
  const forward = text.match(
    /avance(?:z)?\s+de\s+([0-9]+|un|une|deux|trois|quatre|cinq|six)\s+case/i,
  );
  if (forward) return parse(forward[1]);
  const backward = text.match(
    /recule(?:z)?\s+de\s+([0-9]+|un|une|deux|trois|quatre|cinq|six)\s+case/i,
  );
  if (backward) return -parse(backward[1]);
  return 0;
}

function extractSkipTurns(text: string): number {
  if (/Passez trois tours/i.test(text)) return 3;
  if (/Passez deux tours/i.test(text)) return 2;
  if (
    /Passez votre prochain tour/i.test(text) ||
    /Passez votre tour/i.test(text)
  )
    return 1;
  return 0;
}

function extractTargetPlace(text: string): string | null {
  const m1 = text.match(/avancez\s+jusqu[’']?à\s+la\s+gare\s+de\s+([^.,]+)/i);
  if (m1?.[1]) return `Gare de ${m1[1].trim()}`;
  const m2 = text.match(/avancez\s+(?:directement\s+)?à\s+([^.,]+)/i);
  if (m2?.[1]) return m2[1].trim();
  return null;
}

function isGetOutOfJailCard(text: string): boolean {
  return /Sortie de prison/i.test(text) || /Lib[ée]ration/i.test(text);
}

function extractAllPlayersMoney(
  textRaw: string,
): null | { kind: 'pay' | 'receive'; amount: number; toBank: boolean } {
  const text = String(textRaw ?? '');
  const toBank = /banque/i.test(text);

  const pay = text.match(/Tous\s+les\s+joueurs\s+(?:paient|payent)\s+(\d+)/i);
  if (pay?.[1]) {
    const n = Number(pay[1]);
    if (Number.isFinite(n) && n > 0)
      return { kind: 'pay', amount: Math.trunc(n), toBank };
  }

  const receive = text.match(/Tous\s+les\s+joueurs\s+re[çc]oivent\s+(\d+)/i);
  if (receive?.[1]) {
    const n = Number(receive[1]);
    if (Number.isFinite(n) && n > 0)
      return { kind: 'receive', amount: Math.trunc(n), toBank };
  }

  return null;
}

function mentionsInfrastructureLoss(text: string): boolean {
  return (
    /perd(?:ez|s)?\s+une\s+infrastructure/i.test(text) ||
    /perds\s+une\s+infrastructure/i.test(text)
  );
}
